import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import './index.css';
import Menu from './components/Menu';
import Hud, { Banner } from './components/Hud';
import { GameOver, PauseMenu } from './components/Overlays';
import { Game, HudState, JudgePop, RunResult } from './game/engine';
import { DIFFS, SONGS } from './game/songs';
import { bestKey, betterRank, loadSave, SaveData, storeSave } from './game/save';
import { sound } from './game/audio';

type Screen = 'menu' | 'play' | 'pause' | 'over';

const EMPTY: HudState = { score: 0, combo: 0, mult: 1, health: 100, accuracy: 1, progress: 0, fever: 0, feverT: 0, shield: 0, section: 'Prepárate' };

export default function App() {
  const hostRef = useRef<HTMLDivElement>(null);
  const gameRef = useRef<Game | null>(null);
  const [screen, setScreen] = useState<Screen>('menu');
  const screenRef = useRef<Screen>('menu');
  const [hud, setHud] = useState<HudState>(EMPTY);
  const [pop, setPop] = useState<JudgePop | null>(null);
  const [banner, setBanner] = useState<Banner | null>(null);
  const [save, setSave] = useState<SaveData>(() => loadSave());
  const saveRef = useRef(save);
  const [result, setResult] = useState<{ r: RunResult; record: boolean; prevBest: number } | null>(null);
  const [muted, setMuted] = useState(false);
  const [touch] = useState(() => typeof window !== 'undefined' && (window.matchMedia?.('(pointer: coarse)').matches ?? false));
  const bannerId = useRef(0);

  const go = (s: Screen) => { screenRef.current = s; setScreen(s); };
  const persist = (s: SaveData) => { saveRef.current = s; setSave(s); storeSave(s); };

  const setPaused = useCallback((p: boolean) => {
    const g = gameRef.current; if (!g) return;
    g.setPaused(p);
    go(p ? 'pause' : 'play');
  }, []);

  useEffect(() => {
    const host = hostRef.current;
    if (!host) return;
    const game = new Game(host, {
      onHud: h => setHud(h),
      onJudge: p => setPop(p),
      onBanner: (text, color) => setBanner({ id: ++bannerId.current, text, color }),
      onAutoPause: () => { if (screenRef.current === 'play') setPaused(true); },
      onEnd: r => {
        const s = saveRef.current;
        const k = bestKey(r.songId, r.diffId);
        const prevBest = s.best[k] ?? 0;
        const record = r.score > prevBest && r.score > 0;
        persist({ ...s, best: { ...s.best, [k]: Math.max(prevBest, r.score) }, rank: r.cleared ? { ...s.rank, [k]: betterRank(s.rank[k], r.rank) } : s.rank });
        setResult({ r, record, prevBest });
        setPop(null);
        go('over');
        if (record || r.rank === 'S') {
          try { confetti({ particleCount: 150, spread: 100, origin: { y: 0.4 }, colors: ['#ff2fd0', '#22e6ff', '#b6ff3b', '#ffe14a'] }); } catch { /* sin confeti */ }
        }
      },
    });
    gameRef.current = game;
    return () => { game.dispose(); gameRef.current = null; };
  }, [setPaused]);

  const start = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    sound.init();
    (document.activeElement as HTMLElement | null)?.blur?.();
    const s = saveRef.current;
    const song = SONGS.find(x => x.id === s.song) ?? SONGS[0];
    const diff = DIFFS.find(x => x.id === s.diff) ?? DIFFS[1];
    setHud(EMPTY); setPop(null); setBanner(null); setResult(null);
    g.newRun(song, diff);
    go('play');
  }, []);

  const toMenu = useCallback(() => {
    gameRef.current?.toAttract();
    setPop(null); setBanner(null);
    go('menu');
  }, []);

  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const s = screenRef.current;
      if (e.code === 'Escape' || e.code === 'KeyP') {
        if (s === 'play') setPaused(true); else if (s === 'pause') setPaused(false);
      } else if (e.code === 'Enter' && (s === 'menu' || s === 'over')) start();
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [setPaused, start]);

  // Limpia el cartel de sección/combo tras su animación
  useEffect(() => {
    if (!banner) return;
    const id = window.setTimeout(() => setBanner(b => (b && b.id === banner.id ? null : b)), 1500);
    return () => window.clearTimeout(id);
  }, [banner]);

  const toggleMute = () => { sound.init(); sound.setMuted(!muted); setMuted(!muted); };
  const song = SONGS.find(x => x.id === save.song) ?? SONGS[0];

  return (
    <div className="rn-root relative h-screen min-h-[420px] w-full overflow-hidden bg-[#05010f]">
      <div ref={hostRef} className="absolute inset-0" />
      <div className="rn-vignette absolute inset-0" />
      <div className="rn-scan absolute inset-0 opacity-50" />
      {screen === 'menu' && (
        <Menu save={save} muted={muted} onToggleMute={toggleMute} onPlay={start}
          onSong={id => { sound.init(); sound.click(); persist({ ...saveRef.current, song: id }); }}
          onDiff={id => { sound.init(); sound.click(); persist({ ...saveRef.current, diff: id }); }} />
      )}
      {(screen === 'play' || screen === 'pause') && gameRef.current && (
        <Hud hud={hud} songName={song.name} songColor={song.color} pop={pop} banner={banner} muted={muted} touch={touch}
          input={gameRef.current.input} onPause={() => setPaused(true)} onToggleMute={toggleMute} />
      )}
      {screen === 'pause' && <PauseMenu onResume={() => setPaused(false)} onRestart={start} onMenu={toMenu} />}
      {screen === 'over' && result && (
        <GameOver r={result.r} songName={SONGS.find(x => x.id === result.r.songId)?.name ?? ''}
          diffName={DIFFS.find(x => x.id === result.r.diffId)?.name ?? ''}
          best={Math.max(result.prevBest, result.r.score)} isRecord={result.record} onRetry={start} onMenu={toMenu} />
      )}
    </div>
  );
}

import { Heart, Pause, Shield, Volume2, VolumeX, Zap } from 'lucide-react';
import clsx from 'clsx';
import type { HudState, JudgePop } from '../game/engine';
import type { Input } from '../game/input';

export interface Banner { id: number; text: string; color: string }

interface Props {
  hud: HudState;
  songName: string;
  songColor: string;
  pop: JudgePop | null;
  banner: Banner | null;
  muted: boolean;
  touch: boolean;
  input: Input;
  onPause(): void;
  onToggleMute(): void;
}

const GRADE: Record<string, [string, string]> = {
  perfect: ['¡PERFECTO!', '#7dfcff'],
  good: ['BIEN', '#b6ff3b'],
  miss: ['FALLO', '#ff4d6d'],
  blocked: ['¡BLOQUEADO!', '#9ff6ff'],
};
const LANE_COL = ['#ff2fd0', '#22e6ff', '#b6ff3b', '#ffa62e'];
const LANE_KEY = ['D', 'F', 'J', 'K'];

function Bar({ v, color, glow }: { v: number; color: string; glow?: boolean }) {
  return (
    <div className="h-2 w-full overflow-hidden rounded-full bg-white/10">
      <div className="h-full rounded-full transition-[width] duration-150" style={{ width: `${Math.max(0, Math.min(1, v)) * 100}%`, background: color, boxShadow: glow ? `0 0 10px ${color}` : undefined }} />
    </div>
  );
}

export default function Hud({ hud, songName, songColor, pop, banner, muted, touch, input, onPause, onToggleMute }: Props) {
  const feverOn = hud.feverT > 0;
  const hpCol = hud.health > 55 ? '#b6ff3b' : hud.health > 25 ? '#ffa62e' : '#ff4d6d';
  return (
    <div className="pointer-events-none absolute inset-0 text-white">
      {feverOn && <div className="absolute inset-0" style={{ boxShadow: 'inset 0 0 120px rgba(255,210,60,0.35)' }} />}
      {pop?.grade === 'miss' && <div key={pop.id} className="rn-flash absolute inset-0" style={{ boxShadow: 'inset 0 0 140px rgba(255,40,90,0.6)' }} />}
      {/* Puntos y multiplicador */}
      <div className="absolute left-3 top-3 sm:left-5 sm:top-4">
        <div className="text-[10px] font-bold uppercase tracking-[0.3em] text-violet-300">Puntos</div>
        <div className="rn-mono text-3xl font-black sm:text-4xl" style={{ textShadow: '0 0 14px rgba(255,47,208,0.7)' }}>{hud.score.toLocaleString('es')}</div>
        <div className={clsx('mt-1 inline-flex items-center gap-1 rounded-md px-2 py-0.5 text-sm font-black', feverOn ? 'rn-fever bg-yellow-300 text-[#2a1400]' : 'rn-glass')}
          style={!feverOn ? { color: ['#fff', '#22e6ff', '#b6ff3b', '#ffa62e', '#ff2fd0'][Math.min(4, Math.floor(hud.mult))] } : undefined}>
          ×{hud.mult}{feverOn && <span className="text-[10px] tracking-widest">SOBRECARGA</span>}
        </div>
      </div>
      {/* Canción, progreso y energía */}
      <div className="rn-glass absolute left-1/2 top-3 w-[min(420px,46vw)] -translate-x-1/2 rounded-xl px-4 py-2">
        <div className="flex items-baseline justify-between gap-2">
          <div className="truncate text-sm font-black italic" style={{ color: songColor }}>{songName}</div>
          <div className="text-[10px] font-bold uppercase tracking-[0.2em] text-violet-300">{hud.section}</div>
        </div>
        <div className="mt-1"><Bar v={hud.progress} color={songColor} glow /></div>
        <div className="mt-1.5 flex items-center gap-2">
          <Heart className="h-3.5 w-3.5 shrink-0" style={{ color: hpCol }} />
          <Bar v={hud.health / 100} color={hpCol} glow={hud.health < 30} />
        </div>
      </div>
      {/* Precisión, escudo, botones */}
      <div className="absolute right-3 top-3 flex items-start gap-2 sm:right-5 sm:top-4">
        <div className="text-right">
          <div className="text-[10px] font-bold uppercase tracking-[0.3em] text-violet-300">Precisión</div>
          <div className="rn-mono text-2xl font-black text-cyan-200">{(hud.accuracy * 100).toFixed(1)}%</div>
          <div className="mt-1 flex justify-end gap-1">
            {[0, 1].map(i => <Shield key={i} className={clsx('h-4 w-4', i < hud.shield ? 'text-cyan-200' : 'text-white/15')} style={i < hud.shield ? { filter: 'drop-shadow(0 0 6px #9ff6ff)' } : undefined} />)}
          </div>
        </div>
        <button onClick={onToggleMute} className="rn-glass pointer-events-auto rounded-full p-2.5" aria-label="Silencio">
          {muted ? <VolumeX className="h-5 w-5" /> : <Volume2 className="h-5 w-5" />}
        </button>
        <button onClick={onPause} className="rn-glass pointer-events-auto rounded-full p-2.5" aria-label="Pausa"><Pause className="h-5 w-5" /></button>
      </div>
      {/* Combo y juicio */}
      <div className="absolute left-[4%] top-[34%] text-center sm:left-[13%]">
        {hud.combo >= 3 && (
          <div key={hud.combo} className="rn-combo">
            <div className="rn-mono text-6xl font-black leading-none sm:text-7xl" style={{ color: feverOn ? '#ffe14a' : '#ffffff', textShadow: `0 0 18px ${feverOn ? '#ffb02e' : '#ff2fd0'}, 0 0 40px ${feverOn ? '#ffb02e' : '#a35bff'}` }}>{hud.combo}</div>
            <div className="text-xs font-black tracking-[0.5em] text-violet-200/90">COMBO</div>
          </div>
        )}
      </div>
      {pop && (
        <div key={pop.id} className="rn-pop absolute left-1/2 top-[47%] whitespace-nowrap text-center">
          <div className="rn-neon text-3xl font-black italic sm:text-4xl" style={{ color: GRADE[pop.grade][1] }}>{GRADE[pop.grade][0]}</div>
          {pop.grade === 'good' && <div className="text-[10px] font-bold tracking-[0.3em] text-violet-200/80">{pop.late ? 'TARDE' : 'PRONTO'}</div>}
        </div>
      )}
      {banner && (
        <div key={banner.id} className="rn-banner absolute left-1/2 top-[19%] whitespace-nowrap text-2xl font-black italic sm:text-3xl" style={{ color: banner.color, textShadow: `0 0 18px ${banner.color}` }}>
          {banner.text}
        </div>
      )}
      {/* Sobrecarga */}
      <div className={clsx('absolute left-3 w-40 sm:left-5 sm:w-52', touch ? 'bottom-28' : 'bottom-5')}>
        <div className="mb-1 flex items-center gap-1.5 text-[10px] font-black uppercase tracking-[0.25em] text-yellow-300">
          <Zap className="h-3.5 w-3.5" /> Sobrecarga
          {!feverOn && hud.fever >= 0.5 && <span className="ml-auto animate-pulse text-white">¡Espacio!</span>}
        </div>
        <Bar v={feverOn ? hud.feverT / 10 : hud.fever} color={feverOn ? '#ffe14a' : hud.fever >= 0.5 ? '#ffd040' : '#a37a20'} glow={hud.fever >= 0.5 || feverOn} />
      </div>
      {touch && (
        <div className="pointer-events-auto absolute inset-x-0 bottom-0 flex h-24 gap-1.5 px-2 pb-2">
          {[0, 1, 2, 3].map(l => (
            <button key={l} className="flex-1 rounded-xl border-2 text-lg font-black active:brightness-150"
              style={{ borderColor: LANE_COL[l], background: `${LANE_COL[l]}22`, color: LANE_COL[l], boxShadow: `inset 0 0 18px ${LANE_COL[l]}44` }}
              onPointerDown={e => { e.preventDefault(); (e.currentTarget as HTMLElement).setPointerCapture?.(e.pointerId); input.pressLane(l, 'p' + e.pointerId); }}
              onPointerUp={e => input.releaseLane(l, 'p' + e.pointerId)}
              onPointerCancel={e => input.releaseLane(l, 'p' + e.pointerId)}
              onContextMenu={e => e.preventDefault()}>
              {LANE_KEY[l]}
            </button>
          ))}
          <button className="w-16 rounded-xl border-2 border-yellow-300 bg-yellow-300/15 text-yellow-300" onPointerDown={e => { e.preventDefault(); input.fever(); }}>
            <Zap className="mx-auto h-6 w-6" />
          </button>
        </div>
      )}
    </div>
  );
}

import { Disc3, Gauge, Music, Play, Trophy, Volume2, VolumeX, Zap } from 'lucide-react';
import clsx from 'clsx';
import { DIFFS, SONGS } from '../game/songs';
import { bestKey, SaveData } from '../game/save';

interface Props {
  save: SaveData;
  muted: boolean;
  onSong(id: string): void;
  onDiff(id: string): void;
  onToggleMute(): void;
  onPlay(): void;
}

const KEYS: Array<[string, string, string]> = [['D', '←', '#ff2fd0'], ['F', '↓', '#22e6ff'], ['J', '↑', '#b6ff3b'], ['K', '→', '#ffa62e']];

export default function Menu({ save, muted, onSong, onDiff, onToggleMute, onPlay }: Props) {
  const song = SONGS.find(s => s.id === save.song) ?? SONGS[0];
  const best = save.best[bestKey(song.id, save.diff)] ?? 0;
  return (
    <div className="absolute inset-0 overflow-y-auto">
      <div className="pointer-events-none absolute inset-0 bg-gradient-to-r from-[#05010f]/95 via-[#05010f]/70 to-transparent" />
      <div className="relative flex min-h-full flex-col justify-center gap-5 px-5 py-6 sm:px-10 lg:w-[62%]">
        <div className="flex items-start justify-between gap-4">
          <div>
            <div className="mb-1 flex items-center gap-2 text-xs font-bold uppercase tracking-[0.4em] text-cyan-300/80">
              <Disc3 className="h-4 w-4 animate-spin" style={{ animationDuration: '3s' }} /> NONA · Juego de ritmo
            </div>
            <h1 className="rn-title rn-float text-5xl leading-none sm:text-7xl">RITMO NEÓN</h1>
            <p className="mt-3 max-w-xl text-sm text-violet-100/80 sm:text-base">
              Las notas caen al compás de una música generada en vivo. Pulsa justo cuando cruzan el anillo,
              encadena combos y desata la <span className="font-bold text-yellow-300">Sobrecarga</span> con las notas doradas.
            </p>
          </div>
          <button onClick={onToggleMute} className="rn-glass shrink-0 rounded-full p-3 text-white" aria-label="Silencio">
            {muted ? <VolumeX className="h-5 w-5" /> : <Volume2 className="h-5 w-5" />}
          </button>
        </div>

        <div>
          <div className="mb-2 flex items-center gap-2 text-xs font-bold uppercase tracking-[0.3em] text-violet-300"><Music className="h-4 w-4" /> Canción</div>
          <div className="grid grid-cols-1 gap-2 sm:grid-cols-2">
            {SONGS.map(s => {
              const sel = s.id === song.id;
              const b = save.best[bestKey(s.id, save.diff)];
              const r = save.rank[bestKey(s.id, save.diff)];
              return (
                <button key={s.id} onClick={() => onSong(s.id)}
                  className={clsx('rn-glass group relative overflow-hidden rounded-xl px-4 py-3 text-left transition', sel ? 'scale-[1.01]' : 'opacity-75 hover:opacity-100')}
                  style={sel ? { borderColor: s.color, boxShadow: `0 0 24px ${s.color}55, inset 0 0 18px ${s.color}22` } : undefined}>
                  <div className="absolute inset-y-0 left-0 w-1" style={{ background: s.color, boxShadow: `0 0 12px ${s.color}` }} />
                  <div className="flex items-center justify-between gap-2">
                    <div className="text-lg font-black italic text-white">{s.name}</div>
                    {r && <div className="rn-neon text-lg font-black" style={{ color: s.color }}>{r}</div>}
                  </div>
                  <div className="text-xs text-violet-200/70">{s.desc}</div>
                  <div className="mt-1 flex items-center gap-3 text-[11px] font-bold uppercase tracking-wider text-violet-300/80">
                    <span className="rn-mono" style={{ color: s.color }}>{s.bpm} BPM</span>
                    <span>{b ? `Récord ${b.toLocaleString('es')}` : 'Sin récord'}</span>
                  </div>
                </button>
              );
            })}
          </div>
        </div>

        <div className="flex flex-wrap items-end gap-5">
          <div>
            <div className="mb-2 flex items-center gap-2 text-xs font-bold uppercase tracking-[0.3em] text-violet-300"><Gauge className="h-4 w-4" /> Dificultad</div>
            <div className="rn-glass flex rounded-xl p-1">
              {DIFFS.map(d => (
                <button key={d.id} onClick={() => onDiff(d.id)}
                  className={clsx('rounded-lg px-3 py-2 text-sm font-bold transition sm:px-4', save.diff === d.id ? 'text-[#0a0218]' : 'text-violet-200 hover:text-white')}
                  style={save.diff === d.id ? { background: d.color, boxShadow: `0 0 16px ${d.color}` } : undefined}>
                  {d.name}
                </button>
              ))}
            </div>
          </div>
          <div>
            <div className="mb-2 text-xs font-bold uppercase tracking-[0.3em] text-violet-300">Controles</div>
            <div className="flex gap-1.5">
              {KEYS.map(([k, a, c]) => (
                <div key={k} className="rn-glass flex h-11 w-11 flex-col items-center justify-center rounded-lg" style={{ borderColor: c, boxShadow: `0 0 10px ${c}55` }}>
                  <span className="rn-mono text-sm font-black text-white">{k}</span>
                  <span className="text-[10px] leading-none" style={{ color: c }}>{a}</span>
                </div>
              ))}
              <div className="rn-glass flex h-11 items-center gap-1 rounded-lg px-3 text-xs font-bold text-yellow-300"><Zap className="h-4 w-4" /> Espacio</div>
            </div>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-4">
          <button onClick={onPlay} className="rn-btn flex items-center gap-3 rounded-2xl px-10 py-4 text-xl">
            <Play className="h-6 w-6 fill-current" /> Jugar
          </button>
          <div className="rn-glass flex items-center gap-3 rounded-xl px-4 py-2">
            <Trophy className="h-6 w-6 text-yellow-300" />
            <div>
              <div className="text-[10px] font-bold uppercase tracking-[0.25em] text-violet-300">Récord · {song.name}</div>
              <div className="rn-mono text-xl font-black text-white">{best.toLocaleString('es')}</div>
            </div>
          </div>
        </div>
        <p className="text-xs text-violet-300/60">Notas: normales · largas (mantén) · <span className="text-yellow-300">doradas</span> (cargan Sobrecarga) · <span className="text-cyan-200">diamante</span> (escudo contra un fallo). P / Esc: pausa.</p>
      </div>
    </div>
  );
}

import { Home, Play, RotateCcw, Trophy } from 'lucide-react';
import type { RunResult } from '../game/engine';

export function PauseMenu({ onResume, onRestart, onMenu }: { onResume(): void; onRestart(): void; onMenu(): void }) {
  return (
    <div className="absolute inset-0 flex items-center justify-center bg-[#05010f]/70 p-4 backdrop-blur-sm">
      <div className="rn-glass w-full max-w-xs rounded-2xl p-6 text-center">
        <h2 className="rn-title mb-5 text-4xl">PAUSA</h2>
        <div className="flex flex-col gap-3">
          <button onClick={onResume} className="rn-btn flex items-center justify-center gap-2 rounded-xl py-3"><Play className="h-5 w-5 fill-current" /> Continuar</button>
          <button onClick={onRestart} className="rn-glass flex items-center justify-center gap-2 rounded-xl py-3 font-bold text-white hover:bg-white/10"><RotateCcw className="h-5 w-5" /> Reiniciar</button>
          <button onClick={onMenu} className="rn-glass flex items-center justify-center gap-2 rounded-xl py-3 font-bold text-white hover:bg-white/10"><Home className="h-5 w-5" /> Menú</button>
        </div>
      </div>
    </div>
  );
}

const RANK_COL: Record<string, string> = { S: '#ffe14a', A: '#b6ff3b', B: '#22e6ff', C: '#a35bff', D: '#ff8ae8', F: '#ff4d6d' };

interface OverProps { r: RunResult; songName: string; diffName: string; best: number; isRecord: boolean; onRetry(): void; onMenu(): void }

export function GameOver({ r, songName, diffName, best, isRecord, onRetry, onMenu }: OverProps) {
  const stats: Array<[string, string | number, string]> = [
    ['Perfecto', r.perfect, '#7dfcff'], ['Bien', r.good, '#b6ff3b'], ['Fallo', r.miss, '#ff4d6d'],
    ['Combo máx.', r.maxCombo, '#ff2fd0'], ['Precisión', `${(r.accuracy * 100).toFixed(1)}%`, '#ffffff'],
  ];
  const col = RANK_COL[r.rank] ?? '#fff';
  return (
    <div className="absolute inset-0 flex items-center justify-center overflow-y-auto bg-[#05010f]/75 p-4 backdrop-blur-sm">
      <div className="rn-glass w-full max-w-md rounded-2xl p-6 text-center">
        <div className="text-xs font-bold uppercase tracking-[0.35em] text-violet-300">{songName} · {diffName}</div>
        <h2 className="rn-title mt-1 text-3xl sm:text-4xl">{r.cleared ? '¡CANCIÓN COMPLETADA!' : 'SEÑAL PERDIDA'}</h2>
        <div className="mt-3 flex items-center justify-center gap-6">
          <div className="rn-neon text-8xl font-black italic leading-none" style={{ color: col }}>{r.rank}</div>
          <div className="text-left">
            <div className="text-[10px] font-bold uppercase tracking-[0.3em] text-violet-300">Puntuación</div>
            <div className="rn-mono text-3xl font-black text-white">{r.score.toLocaleString('es')}</div>
            {isRecord
              ? <div className="mt-1 inline-flex items-center gap-1 rounded-md bg-yellow-300 px-2 py-0.5 text-xs font-black text-[#2a1400]"><Trophy className="h-3.5 w-3.5" /> ¡NUEVO RÉCORD!</div>
              : <div className="text-xs text-violet-300">Récord: {best.toLocaleString('es')}</div>}
          </div>
        </div>
        <div className="mt-5 grid grid-cols-5 gap-1.5">
          {stats.map(([k, v, c]) => (
            <div key={k} className="rounded-lg bg-white/5 px-1 py-2">
              <div className="rn-mono text-lg font-black" style={{ color: c }}>{v}</div>
              <div className="text-[9px] font-bold uppercase tracking-wider text-violet-300">{k}</div>
            </div>
          ))}
        </div>
        <div className="mt-6 flex gap-3">
          <button onClick={onRetry} className="rn-btn flex flex-1 items-center justify-center gap-2 rounded-xl py-3"><RotateCcw className="h-5 w-5" /> Reintentar</button>
          <button onClick={onMenu} className="rn-glass flex flex-1 items-center justify-center gap-2 rounded-xl py-3 font-bold text-white hover:bg-white/10"><Home className="h-5 w-5" /> Menú</button>
        </div>
      </div>
    </div>
  );
}

// Sintetizador Web Audio: instrumentos de la canción (programados con currentTime) y efectos.
import type { Hit } from './songs';

const mtof = (m: number) => 440 * Math.pow(2, (m - 69) / 12);

class Sound {
  ctx: AudioContext | null = null;
  private master!: GainNode;
  private music!: GainNode;
  private sfx!: GainNode;
  private leadBus!: GainNode;
  private delay!: DelayNode;
  private noise!: AudioBuffer;
  muted = false;
  leadType: OscillatorType = 'sawtooth';

  /** Llamar en un gesto del usuario. Si falla, el juego sigue con reloj de respaldo. */
  init() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {}); return; }
    try {
      const AC = window.AudioContext || (window as any).webkitAudioContext;
      if (!AC) return;
      const c: AudioContext = new AC();
      this.ctx = c;
      this.master = c.createGain(); this.master.gain.value = this.muted ? 0 : 0.8;
      const comp = c.createDynamicsCompressor();
      comp.threshold.value = -14; comp.ratio.value = 4;
      this.master.connect(comp); comp.connect(c.destination);
      this.music = c.createGain(); this.music.gain.value = 0.7; this.music.connect(this.master);
      this.sfx = c.createGain(); this.sfx.gain.value = 0.55; this.sfx.connect(this.master);
      this.leadBus = c.createGain(); this.leadBus.connect(this.music);
      this.delay = c.createDelay(1);
      const fb = c.createGain(); fb.gain.value = 0.32;
      const wet = c.createGain(); wet.gain.value = 0.28;
      this.leadBus.connect(this.delay); this.delay.connect(fb); fb.connect(this.delay); this.delay.connect(wet); wet.connect(this.music);
      this.noise = c.createBuffer(1, c.sampleRate, c.sampleRate);
      const d = this.noise.getChannelData(0);
      for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
      if (c.state === 'suspended') c.resume().catch(() => {});
    } catch { this.ctx = null; }
  }
  get running() { return !!this.ctx && this.ctx.state === 'running'; }
  suspend() { this.ctx?.suspend().catch(() => {}); }
  resume() { if (this.ctx && this.ctx.state !== 'running') this.ctx.resume().catch(() => {}); }
  setMuted(m: boolean) {
    this.muted = m;
    if (this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.8, this.ctx.currentTime, 0.02);
  }
  /** Ajusta el eco al tempo y el timbre del lead de la canción. */
  configure(stepDur: number, lead: OscillatorType) {
    this.leadType = lead;
    if (this.ctx) this.delay.delayTime.setValueAtTime(Math.min(0.9, stepDur * 3), this.ctx.currentTime);
  }
  /** Baja la melodía al fallar (como si la banda se desafinara). */
  setLead(level: number) {
    if (this.ctx) this.leadBus.gain.setTargetAtTime(level, this.ctx.currentTime, 0.04);
  }
  private env(t: number, peak: number, attack: number, decay: number, dest: AudioNode) {
    const g = this.ctx!.createGain();
    g.gain.setValueAtTime(0.0001, t);
    g.gain.linearRampToValueAtTime(peak, t + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, t + attack + decay);
    g.connect(dest);
    return g;
  }
  private osc(type: OscillatorType, f: number, t: number, dur: number, dest: AudioNode, detune = 0) {
    const o = this.ctx!.createOscillator();
    o.type = type; o.frequency.setValueAtTime(f, t); o.detune.value = detune;
    o.connect(dest); o.start(t); o.stop(t + dur + 0.05);
    return o;
  }
  private noiseHit(t: number, dur: number, type: BiquadFilterType, freq: number, peak: number, dest: AudioNode) {
    const c = this.ctx!;
    const s = c.createBufferSource(); s.buffer = this.noise;
    const f = c.createBiquadFilter(); f.type = type; f.frequency.value = freq;
    s.connect(f); f.connect(this.env(t, peak, 0.002, dur, dest));
    s.start(t, Math.random() * 0.5); s.stop(t + dur + 0.05);
  }
  private filtered(t: number, freq: number, q = 1) {
    const f = this.ctx!.createBiquadFilter(); f.type = 'lowpass'; f.frequency.setValueAtTime(freq, t); f.Q.value = q;
    return f;
  }

  /** Programa un evento de la partitura en el instante exacto `t` (tiempo del AudioContext). */
  play(h: Hit, t: number, stepDur: number) {
    const c = this.ctx; if (!c) return;
    t = Math.max(t, c.currentTime);
    const v = h.vel, M = this.music;
    switch (h.inst) {
      case 'kick': {
        const o = this.osc('sine', 150, t, 0.4, this.env(t, v, 0.002, 0.38, M));
        o.frequency.exponentialRampToValueAtTime(42, t + 0.12);
        break;
      }
      case 'snare':
        this.noiseHit(t, 0.17, 'bandpass', 1900, v * 0.55, M);
        this.osc('triangle', 190, t, 0.1, this.env(t, v * 0.35, 0.002, 0.09, M));
        break;
      case 'clap':
        for (let i = 0; i < 3; i++) this.noiseHit(t + i * 0.011, i === 2 ? 0.16 : 0.02, 'bandpass', 1200, v * 0.45, M);
        break;
      case 'hat': this.noiseHit(t, 0.035, 'highpass', 7500, v * 0.22, M); break;
      case 'ohat': this.noiseHit(t, 0.17, 'highpass', 7000, v * 0.17, M); break;
      case 'bass': {
        const dur = h.len * stepDur * 0.9;
        const f = this.filtered(t, 950, 4); f.frequency.exponentialRampToValueAtTime(180, t + dur);
        f.connect(this.env(t, v * 0.38, 0.005, dur, M));
        this.osc('sawtooth', mtof(h.midi), t, dur, f);
        this.osc('square', mtof(h.midi - 12), t, dur, f);
        break;
      }
      case 'lead': {
        const dur = Math.max(0.12, h.len * stepDur * 0.92);
        const f = this.filtered(t, 3200, 2); f.frequency.exponentialRampToValueAtTime(1100, t + dur);
        f.connect(this.env(t, v * 0.16, 0.008, dur, this.leadBus));
        const fr = mtof(h.midi);
        this.osc(this.leadType, fr, t, dur, f, -7);
        this.osc(this.leadType, fr, t, dur, f, 7);
        break;
      }
      case 'pad': {
        const dur = h.len * stepDur;
        const f = this.filtered(t, 1300);
        const g = c.createGain();
        g.gain.setValueAtTime(0.0001, t);
        g.gain.linearRampToValueAtTime(v * 0.05, t + 0.25);
        g.gain.setValueAtTime(v * 0.05, t + dur * 0.8);
        g.gain.linearRampToValueAtTime(0.0001, t + dur);
        f.connect(g); g.connect(M);
        this.osc('sawtooth', mtof(h.midi), t, dur, f, -9);
        this.osc('sawtooth', mtof(h.midi), t, dur, f, 9);
        break;
      }
      case 'arp': {
        const f = this.filtered(t, 2400);
        f.connect(this.env(t, v * 0.05, 0.002, 0.09, M));
        this.osc('square', mtof(h.midi), t, 0.1, f);
        break;
      }
    }
  }
  // ---------- Efectos ----------
  private blip(type: OscillatorType, f0: number, f1: number, dur: number, peak: number) {
    const c = this.ctx; if (!c) return;
    const t = c.currentTime;
    const o = this.osc(type, f0, t, dur, this.env(t, peak, 0.003, dur, this.sfx));
    o.frequency.exponentialRampToValueAtTime(f1, t + dur);
  }
  perfect(lane: number) { this.blip('sine', 1046 * Math.pow(1.122, lane), 1568 * Math.pow(1.122, lane), 0.09, 0.22); }
  good(lane: number) { this.blip('triangle', 784 * Math.pow(1.122, lane), 880, 0.07, 0.18); }
  tap() { this.blip('sine', 300, 220, 0.04, 0.08); }
  miss() {
    const c = this.ctx; if (!c) return;
    this.noiseHit(c.currentTime, 0.14, 'lowpass', 500, 0.35, this.sfx);
    this.blip('sawtooth', 130, 55, 0.18, 0.12);
  }
  shield() { this.blip('sine', 660, 1320, 0.25, 0.2); this.blip('triangle', 990, 1980, 0.3, 0.12); }
  fever() { this.blip('sawtooth', 180, 1800, 0.7, 0.16); this.blip('square', 360, 2400, 0.6, 0.06); }
  gold() { this.blip('triangle', 1568, 2093, 0.18, 0.18); }
  click() { this.blip('triangle', 700, 900, 0.05, 0.15); }
  fail() { this.blip('sawtooth', 400, 40, 1.2, 0.25); }
  clear() { [0, 4, 7, 12].forEach((s, i) => setTimeout(() => this.blip('square', 523 * Math.pow(2, s / 12), 523 * Math.pow(2, s / 12), 0.2, 0.12), i * 110)); }
}

export const sound = new Sound();

// Motor: une secuenciador (reloj + música), juez, escenario, notas, efectos y entrada.
import * as THREE from 'three';
import { setupRenderer } from './three-compat';
import { LANE_COLORS, LANE_X, TRACK_LEN, World } from './scene';
import { NoteField } from './notes';
import { Fx } from './fx';
import { Sequencer, Pulse } from './sequencer';
import { Grade, Judge, JudgeEvent } from './judge';
import { Input } from './input';
import { sound } from './audio';
import { buildSong, BuiltSong, DiffDef, DIFFS, SongDef, SONGS } from './songs';

export interface HudState {
  score: number; combo: number; mult: number; health: number; accuracy: number; progress: number;
  fever: number; feverT: number; shield: number; section: string;
}
export interface RunResult {
  score: number; maxCombo: number; perfect: number; good: number; miss: number;
  accuracy: number; rank: string; cleared: boolean; songId: string; diffId: string;
}
export interface JudgePop { id: number; grade: Grade; lane: number; combo: number; late: boolean }
export interface GameCallbacks {
  onHud(h: HudState): void;
  onJudge(p: JudgePop): void;
  onBanner(text: string, color: string): void;
  onEnd(r: RunResult): void;
  onAutoPause(): void;
}

const GOLD = 0xffe14a;

export class Game {
  input: Input;
  private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene();
  private camera = new THREE.PerspectiveCamera(60, 1, 0.1, 700);
  private world: World;
  private field: NoteField;
  private fx: Fx;
  private seq = new Sequencer();
  private judge = new Judge(1, 0);
  private song!: BuiltSong;
  private diff: DiffDef = DIFFS[1];
  private mode: 'attract' | 'play' = 'attract';
  private paused = false;
  private ended = false;
  private raf = 0;
  private last = 0;
  private ro: ResizeObserver;
  private bands = [0, 0, 0, 0, 0, 0, 0, 0];
  private kick = 0;
  private hudT = 0;
  private popId = 0;
  private sectionIdx = -1;
  private attractIdx = 0;
  private lookAt = new THREE.Vector3(0, 0, -16);
  private camX = 0;
  constructor(private host: HTMLElement, private cb: GameCallbacks) {
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 2));
    setupRenderer(this.renderer);
    const cv = this.renderer.domElement;
    cv.style.display = 'block'; cv.style.width = '100%'; cv.style.height = '100%';
    host.appendChild(cv);
    this.world = new World(this.scene);
    this.field = new NoteField(this.scene);
    this.fx = new Fx(this.scene);
    this.input = new Input({
      press: (l, s) => this.onPress(l, s),
      release: (l, s) => this.onRelease(l, s),
      fever: () => this.onFever(),
    });
    this.ro = new ResizeObserver(() => this.resize());
    this.ro.observe(host);
    this.resize();
    document.addEventListener('visibilitychange', this.onVis);
    this.toAttract();
    this.last = performance.now();
    this.raf = requestAnimationFrame(this.loop);
  }
  private get speed() { return this.diff.speed; }
  private get approach() { return TRACK_LEN / this.speed; }
  private resize() {
    const w = Math.max(1, this.host.clientWidth), h = Math.max(1, this.host.clientHeight);
    this.renderer.setSize(w, h, false);
    this.camera.aspect = w / h;
    // En pantallas verticales alejamos la cámara para que quepan los 4 carriles
    this.camera.fov = w / h < 1 ? 74 : 60;
    this.camera.updateProjectionMatrix();
  }
  private onVis = () => { if (document.hidden && this.mode === 'play' && !this.paused && !this.ended) this.cb.onAutoPause(); };

  /** Demo automática de fondo para el menú (sin sonido). */
  toAttract() {
    sound.resume();
    sound.setLead(1);
    this.mode = 'attract'; this.paused = false; this.ended = false;
    this.diff = DIFFS[2];
    this.song = buildSong(SONGS[this.attractIdx++ % SONGS.length], this.diff);
    this.judge = new Judge(1, 0);
    this.seq.start(this.song, true, this.song.sections[2].start - 2);
    this.fx.clear();
  }
  newRun(def: SongDef, diff: DiffDef) {
    this.diff = diff;
    this.song = buildSong(def, diff);
    sound.resume();
    sound.configure(this.song.stepDur, def.lead);
    sound.setLead(1);
    this.judge = new Judge(diff.window, diff.drain);
    this.seq.start(this.song, false);
    this.mode = 'play'; this.paused = false; this.ended = false;
    this.sectionIdx = -1;
    this.fx.clear();
    this.emitHud();
  }
  setPaused(p: boolean) {
    if (this.mode !== 'play' || this.ended) return;
    this.paused = p;
    if (p) this.seq.pause(); else this.seq.resume();
  }

  /** Convierte la marca de tiempo del evento de teclado en tiempo de canción (compensa el retraso del frame). */
  private songTimeAt(stamp: number) {
    let lag = (performance.now() - stamp) / 1000;
    if (!(lag > 0)) lag = 0;
    return this.seq.time() - Math.min(lag, 0.3);
  }
  private onPress(lane: number, stamp: number) {
    if (this.mode !== 'play' || this.paused || this.ended) return;
    this.field.pressLane(lane);
    const ev = this.judge.press(lane, this.songTimeAt(stamp));
    if (ev) this.handle(ev); else sound.tap();
  }
  private onRelease(lane: number, stamp: number) {
    if (this.mode !== 'play' || this.paused || this.ended) return;
    const ev = this.judge.release(lane, this.songTimeAt(stamp));
    if (ev) this.handle(ev);
  }
  private onFever() {
    if (this.mode !== 'play' || this.paused || this.ended) return;
    if (!this.judge.activateFever()) return;
    sound.fever();
    this.cb.onBanner('¡SOBRECARGA ×2!', '#ffe14a');
    for (let l = 0; l < 4; l++) { this.fx.burst(LANE_X[l], 0, GOLD, 14, 1.3); this.field.flashLane(l, 1); }
    this.fx.shake = 0.4;
  }
  private handle(ev: JudgeEvent) {
    const play = this.mode === 'play';
    const x = LANE_X[ev.lane];
    const col = ev.kind === 'gold' ? GOLD : ev.kind === 'shield' ? 0x9ff6ff : LANE_COLORS[ev.lane];
    const fever = this.judge.feverT > 0;
    if (ev.grade === 'perfect' || ev.grade === 'good') {
      const p = ev.grade === 'perfect';
      this.fx.burst(x, 0, fever ? GOLD : col, ev.holdEnd ? 26 : p ? 16 : 8, p ? 1.1 : 0.8);
      this.fx.ring(x, 0, col, p ? 3.4 : 2);
      this.field.flashLane(ev.lane, p ? 1 : 0.6);
      if (play) {
        if (p) sound.perfect(ev.lane); else sound.good(ev.lane);
        sound.setLead(1);
        if (ev.kind === 'gold' && !ev.holdEnd) { sound.gold(); this.fx.ring(x, 0, GOLD, 6); }
        if (ev.kind === 'shield' && !ev.holdEnd) { sound.shield(); this.cb.onBanner('+ ESCUDO', '#9ff6ff'); }
        const c = this.judge.combo;
        if (c > 0 && c % 50 === 0) {
          this.cb.onBanner(`¡${c} COMBO!`, '#ff2fd0');
          for (let l = 0; l < 4; l++) this.fx.burst(LANE_X[l], 0, LANE_COLORS[l], 10, 1.4);
        }
      }
    } else if (ev.grade === 'blocked') {
      this.fx.ring(x, 0, 0x9ff6ff, 5);
      if (play) { sound.shield(); this.cb.onBanner('ESCUDO USADO', '#9ff6ff'); }
    } else {
      this.fx.shake = Math.max(this.fx.shake, 0.3);
      if (play) { sound.miss(); sound.setLead(0.2); }
    }
    if (play && !ev.holdEnd) this.cb.onJudge({ id: ++this.popId, grade: ev.grade, lane: ev.lane, combo: this.judge.combo, late: ev.delta > 0 });
  }

  /** Cada evento musical excita bandas del "ecualizador" visual: [banda, nivel]. */
  private absorb(pulses: Pulse[]) {
    const B: Record<string, number[]> = { kick: [0, 1, 1, 0.8], snare: [3, 1, 4, 0.7], clap: [3, 1, 4, 0.7], hat: [6, 0.6, 7, 0.8], ohat: [6, 0.6, 7, 0.8], bass: [1, 0.75, 2, 0.8], arp: [5, 0.55], pad: [2, 0.6] };
    for (const p of pulses) {
      if (p.inst === 'kick') this.kick = 1;
      const m = p.inst === 'lead' ? [4 + (p.midi % 3), 0.95] : B[p.inst];
      for (let i = 0; i < m.length; i += 2) this.bands[m[i]] = Math.max(this.bands[m[i]], m[i + 1]);
    }
  }
  private finish(cleared: boolean) {
    this.ended = true;
    sound.setLead(1);
    if (cleared) sound.clear(); else sound.fail();
    const j = this.judge;
    const r: RunResult = {
      score: j.score, maxCombo: j.maxCombo, perfect: j.perfect, good: j.good, miss: j.miss,
      accuracy: j.accuracy, rank: cleared ? j.rank : 'F', cleared, songId: this.song.def.id, diffId: this.diff.id,
    };
    this.seq.stop();
    this.cb.onEnd(r);
    this.toAttract();
  }
  private emitHud() {
    const j = this.judge;
    const t = this.seq.time();
    const secs = this.song.sections;
    let si = 0;
    while (si + 1 < secs.length && secs[si + 1].start <= t) si++;
    this.cb.onHud({
      score: j.score, combo: j.combo, mult: j.mult, health: j.health, accuracy: j.accuracy,
      progress: Math.max(0, Math.min(1, t / this.song.duration)), fever: j.fever, feverT: j.feverT,
      shield: j.shield, section: t < 0 ? 'Prepárate' : secs[si].name,
    });
  }
  private loop = (now: number) => {
    this.raf = requestAnimationFrame(this.loop);
    const wall = Math.max(0, Math.min(0.5, (now - this.last) / 1000));
    this.last = now;
    const dt = Math.min(0.05, wall);
    const j = this.judge;
    if (!this.paused) {
      this.seq.update(wall);
      const t = this.seq.time();
      for (const n of this.seq.spawn(this.approach)) j.add(n);
      if (this.mode === 'attract') {
        for (const n of j.active) if (n.state === 0 && n.time <= t) {
          const ev = j.press(n.lane, n.time);
          if (ev) { this.field.pressLane(n.lane); this.handle(ev); }
        }
        if (t > this.song.duration + 0.5) this.toAttract();
      }
      for (const ev of j.update(t, dt)) this.handle(ev);
      this.absorb(this.seq.takePulses());
      const decay = Math.exp(-dt * 5);
      for (let i = 0; i < 8; i++) this.bands[i] *= decay;
      this.kick *= Math.exp(-dt * 7);
      if (this.mode === 'play' && !this.ended) {
        const secs = this.song.sections;
        let si = -1;
        while (si + 1 < secs.length && secs[si + 1].start <= t) si++;
        if (si !== this.sectionIdx) {
          this.sectionIdx = si;
          if (si >= 0) this.cb.onBanner(secs[si].name.toUpperCase(), this.song.def.color);
        }
        this.hudT -= wall;
        if (this.hudT <= 0) { this.hudT = 0.08; this.emitHud(); }
        if (j.health <= 0) this.finish(false);
        else if (t >= this.song.duration + 0.8) this.finish(true);
      }
      const fever = this.judge.feverT > 0;
      const tt = this.seq.time();
      this.world.update(tt, dt, tt * this.speed, this.kick, this.bands, fever);
      const down = [0, 1, 2, 3].map(l => this.mode === 'play' ? this.input.isDown(l) : !!this.judge.holding[l]);
      this.field.update(tt, dt, this.judge.active, this.speed, this.song.stepDur * 4, down, fever, this.kick);
      this.fx.update(dt);
    }
    const s = this.fx.shake;
    const fever = this.judge.feverT > 0;
    // En el menú desplazamos la vista para que la demo quede a la derecha del panel
    const wantX = this.mode === 'attract' && this.camera.aspect > 1.2 ? -5.5 : 0;
    this.camX += (wantX - this.camX) * Math.min(1, dt * 3);
    this.lookAt.x = this.camX;
    this.camera.position.set(this.camX + (Math.random() - 0.5) * s * 0.5, 5.4 + this.kick * 0.06 + (Math.random() - 0.5) * s * 0.4, 6.8);
    this.camera.lookAt(this.lookAt);
    const fov = (this.camera.aspect < 1 ? 74 : 60) + (fever ? 5 : 0);
    if (Math.abs(this.camera.fov - fov) > 0.05) { this.camera.fov += (fov - this.camera.fov) * Math.min(1, dt * 5); this.camera.updateProjectionMatrix(); }
    this.renderer.render(this.scene, this.camera);
  };
  dispose() {
    cancelAnimationFrame(this.raf);
    this.ro.disconnect();
    document.removeEventListener('visibilitychange', this.onVis);
    this.input.dispose();
    this.seq.stop();
    this.fx.dispose();
    this.field.dispose();
    this.world.dispose();
    this.renderer.dispose();
    this.renderer.domElement.remove();
  }
}

// Efectos: chispas (pool en InstancedMesh), ondas expansivas y sacudida de cámara.
import * as THREE from 'three';

const MAX_SPARKS = 320;
const MAX_RINGS = 14;
const WHITE = new THREE.Color(0xffffff);

interface Spark { x: number; y: number; z: number; vx: number; vy: number; vz: number; life: number; max: number; size: number }
interface Ring { mesh: THREE.Mesh; mat: THREE.MeshBasicMaterial; life: number; grow: number }

export class Fx {
  shake = 0;
  private sparks: Spark[] = [];
  private mesh: THREE.InstancedMesh;
  private rings: Ring[] = [];
  private d = new THREE.Object3D();
  private c = new THREE.Color();
  private geo: THREE.BufferGeometry[] = [];
  private mats: THREE.Material[] = [];
  private cursor = 0;
  constructor(private scene: THREE.Scene) {
    const g = new THREE.OctahedronGeometry(0.12, 0);
    const m = new THREE.MeshBasicMaterial({ transparent: true, blending: THREE.AdditiveBlending, depthWrite: false });
    this.geo.push(g); this.mats.push(m);
    this.mesh = new THREE.InstancedMesh(g, m, MAX_SPARKS);
    this.mesh.frustumCulled = false;
    for (let i = 0; i < MAX_SPARKS; i++) {
      this.mesh.setColorAt(i, this.c.setHex(0xffffff));
      this.sparks.push({ x: 0, y: 0, z: 0, vx: 0, vy: 0, vz: 0, life: 0, max: 1, size: 1 });
    }
    this.mesh.count = 0;
    scene.add(this.mesh);
    const rg = new THREE.RingGeometry(0.7, 0.86, 6, 1).rotateX(-Math.PI / 2);
    this.geo.push(rg);
    for (let i = 0; i < MAX_RINGS; i++) {
      const mat = new THREE.MeshBasicMaterial({ transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide });
      const mesh = new THREE.Mesh(rg, mat);
      mesh.visible = false; mesh.rotation.y = Math.PI / 6;
      scene.add(mesh);
      this.mats.push(mat);
      this.rings.push({ mesh, mat, life: 0, grow: 3 });
    }
  }
  burst(x: number, z: number, color: number, count: number, power = 1) {
    for (let i = 0; i < count; i++) {
      const idx = this.cursor;
      const s = this.sparks[idx];
      this.cursor = (this.cursor + 1) % MAX_SPARKS;
      const a = Math.random() * Math.PI * 2, sp = (2 + Math.random() * 6) * power;
      s.x = x + (Math.random() - 0.5) * 0.6; s.y = 0.3; s.z = z;
      s.vx = Math.cos(a) * sp * 0.6; s.vz = Math.sin(a) * sp * 0.4; s.vy = 3 + Math.random() * 7 * power;
      s.max = s.life = 0.45 + Math.random() * 0.5;
      s.size = 0.7 + Math.random() * 1.1;
      this.mesh.setColorAt(idx, this.c.setHex(color).lerp(WHITE, Math.random() * 0.4));
    }
  }
  ring(x: number, z: number, color: number, grow = 3, y = 0.05) {
    const r = this.rings.find(q => q.life <= 0) ?? this.rings[0];
    r.life = 1; r.grow = grow;
    r.mat.color.setHex(color);
    r.mesh.position.set(x, y, z);
    r.mesh.visible = true;
  }
  update(dt: number) {
    const d = this.d;
    let n = 0;
    for (let i = 0; i < MAX_SPARKS; i++) {
      const s = this.sparks[i];
      if (s.life <= 0) continue;
      s.life -= dt;
      s.vy -= 14 * dt;
      s.x += s.vx * dt; s.y = Math.max(0.05, s.y + s.vy * dt); s.z += s.vz * dt;
      const k = Math.max(0, s.life / s.max) * s.size;
      d.position.set(s.x, s.y, s.z);
      d.rotation.set(s.life * 9, s.life * 7, 0);
      d.scale.set(k, k * 1.6, k);
      d.updateMatrix();
      this.mesh.setMatrixAt(i, d.matrix);
      n = i + 1;
    }
    // Las chispas muertas quedan con escala ~0; count cubre hasta la última viva
    for (let i = 0; i < n; i++) if (this.sparks[i].life <= 0) { d.scale.set(0, 0, 0); d.updateMatrix(); this.mesh.setMatrixAt(i, d.matrix); }
    this.mesh.count = n;
    this.mesh.instanceMatrix.needsUpdate = true;
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
    for (const r of this.rings) {
      if (r.life <= 0) continue;
      r.life -= dt * 2.4;
      const s = 1 + (1 - r.life) * r.grow;
      r.mesh.scale.set(s, 1, s);
      r.mat.opacity = Math.max(0, r.life);
      if (r.life <= 0) r.mesh.visible = false;
    }
    this.shake = Math.max(0, this.shake - dt * 2.5);
  }
  clear() {
    this.sparks.forEach(s => { s.life = 0; });
    this.rings.forEach(r => { r.life = 0; r.mesh.visible = false; });
    this.mesh.count = 0;
  }
  dispose() {
    this.scene.remove(this.mesh);
    this.rings.forEach(r => this.scene.remove(r.mesh));
    this.geo.forEach(g => g.dispose());
    this.mats.forEach(m => m.dispose());
  }
}

// Entrada: D F J K y flechas (← ↓ ↑ →) para los 4 carriles, Espacio para la Sobrecarga, botones táctiles.
const LANE_KEYS: Record<string, number> = {
  KeyD: 0, ArrowLeft: 0, KeyF: 1, ArrowDown: 1, KeyJ: 2, ArrowUp: 2, KeyK: 3, ArrowRight: 3,
};

export interface InputHandlers {
  press(lane: number, stamp: number): void;
  release(lane: number, stamp: number): void;
  fever(): void;
}

export class Input {
  /** Teclas/dedos activos por carril (varias teclas pueden pulsar el mismo carril). */
  private held: Array<Set<string>> = [new Set(), new Set(), new Set(), new Set()];
  constructor(private h: InputHandlers) {
    window.addEventListener('keydown', this.onDown);
    window.addEventListener('keyup', this.onUp);
    window.addEventListener('blur', this.onBlur);
  }
  isDown(lane: number) { return this.held[lane].size > 0; }
  private onDown = (e: KeyboardEvent) => {
    const t = (e.target as HTMLElement | null)?.tagName;
    if (t === 'INPUT' || t === 'TEXTAREA') return;
    if (e.code === 'Space') { e.preventDefault(); if (!e.repeat) this.h.fever(); return; }
    const lane = LANE_KEYS[e.code];
    if (lane === undefined) return;
    e.preventDefault();
    if (e.repeat) return;
    this.pressLane(lane, e.code, e.timeStamp);
  };
  private onUp = (e: KeyboardEvent) => {
    const lane = LANE_KEYS[e.code];
    if (lane !== undefined) this.releaseLane(lane, e.code, e.timeStamp);
  };
  private onBlur = () => {
    for (let l = 0; l < 4; l++) if (this.held[l].size) { this.held[l].clear(); this.h.release(l, performance.now()); }
  };
  pressLane(lane: number, src = 'touch', stamp = performance.now()) {
    const s = this.held[lane];
    const was = s.size > 0;
    s.add(src);
    if (!was) this.h.press(lane, stamp);
  }
  releaseLane(lane: number, src = 'touch', stamp = performance.now()) {
    const s = this.held[lane];
    if (!s.has(src)) return;
    s.delete(src);
    if (s.size === 0) this.h.release(lane, stamp);
  }
  fever() { this.h.fever(); }
  dispose() {
    window.removeEventListener('keydown', this.onDown);
    window.removeEventListener('keyup', this.onUp);
    window.removeEventListener('blur', this.onBlur);
  }
}

// Juez de precisión: Perfecto / Bien / Fallo, combos, multiplicador, energía, Sobrecarga y escudo.
import type { ChartNote, NoteKind } from './songs';

export type Grade = 'perfect' | 'good' | 'miss' | 'blocked';
export interface JudgeEvent { grade: Grade; lane: number; kind: NoteKind; delta: number; holdEnd?: boolean }

export const PERFECT_W = 0.05;
export const GOOD_W = 0.11;
export const MISS_W = 0.15;

export class Judge {
  score = 0; combo = 0; maxCombo = 0; health = 100;
  perfect = 0; good = 0; miss = 0;
  fever = 0; feverT = 0; shield = 0;
  active: ChartNote[] = [];
  holding: Array<ChartNote | null> = [null, null, null, null];
  private holdAcc = 0;
  constructor(public win: number, public drain: number) {}
  get mult() { return Math.min(4, 1 + Math.floor(this.combo / 10)) * (this.feverT > 0 ? 2 : 1); }
  get accuracy() {
    const n = this.perfect + this.good + this.miss;
    return n ? (this.perfect + this.good * 0.65) / n : 1;
  }
  get rank() {
    const a = this.accuracy;
    return a >= 0.95 ? 'S' : a >= 0.88 ? 'A' : a >= 0.78 ? 'B' : a >= 0.65 ? 'C' : 'D';
  }
  add(n: ChartNote) { this.active.push(n); }

  /** Calibración automática de latencia (auriculares Bluetooth, pantallas lentas): aprende el desfase medio. */
  offset = 0;
  press(lane: number, raw: number): JudgeEvent | null {
    const t = raw - this.offset;
    let best: ChartNote | null = null, bd = 1e9;
    for (const n of this.active) {
      if (n.lane !== lane || n.state !== 0) continue;
      const d = Math.abs(t - n.time);
      if (d < bd) { bd = d; best = n; }
    }
    if (best && bd < 0.3) this.offset = Math.max(-0.2, Math.min(0.2, this.offset + (t - best.time) * 0.3));
    if (!best || bd > GOOD_W * this.win) return null;
    const grade: Grade = bd <= PERFECT_W * this.win ? 'perfect' : 'good';
    if (best.kind === 'hold') { best.state = 1; this.holding[lane] = best; } else best.state = 2;
    this.credit(grade, best);
    return { grade, lane, kind: best.kind, delta: t - best.time };
  }
  release(lane: number, t: number): JudgeEvent | null {
    const n = this.holding[lane];
    if (!n) return null;
    this.holding[lane] = null;
    if (t - this.offset >= n.end - 0.12) return this.finishHold(n);
    n.state = 3;
    return this.fail(n);
  }

  /** Avanza el tiempo: notas que pasaron sin tocar, notas largas completadas, puntos por mantener. */
  update(t: number, dt: number): JudgeEvent[] {
    const out: JudgeEvent[] = [];
    if (this.feverT > 0) this.feverT = Math.max(0, this.feverT - dt);
    for (const n of this.active) {
      if (n.state === 0 && t - this.offset - n.time > MISS_W * this.win) { n.state = 3; out.push(this.fail(n)); }
    }
    let held = 0;
    for (let l = 0; l < 4; l++) {
      const n = this.holding[l];
      if (!n) continue;
      if (t >= n.end) { this.holding[l] = null; out.push(this.finishHold(n)); } else held++;
    }
    if (held) {
      this.holdAcc += dt * held;
      while (this.holdAcc > 0.1) { this.holdAcc -= 0.1; this.score += 10 * this.mult; }
    }
    this.active = this.active.filter(n => t < Math.max(n.time, n.end) + 0.6);
    return out;
  }
  activateFever(): boolean {
    if (this.fever < 0.5 || this.feverT > 0) return false;
    this.feverT = 4 + this.fever * 6;
    this.fever = 0;
    return true;
  }
  private finishHold(n: ChartNote): JudgeEvent {
    n.state = 2;
    this.score += 120 * this.mult;
    this.combo++; this.maxCombo = Math.max(this.maxCombo, this.combo);
    return { grade: 'perfect', lane: n.lane, kind: n.kind, delta: 0, holdEnd: true };
  }
  private credit(grade: Grade, n: ChartNote) {
    this.combo++;
    this.maxCombo = Math.max(this.maxCombo, this.combo);
    if (grade === 'perfect') this.perfect++; else this.good++;
    this.score += (grade === 'perfect' ? 300 : 120) * this.mult * (n.kind === 'gold' ? 2 : 1);
    this.health = Math.min(100, this.health + (grade === 'perfect' ? 1.6 : 0.8));
    if (n.kind === 'gold') this.fever = Math.min(1, this.fever + 0.34);
    if (n.kind === 'shield') this.shield = Math.min(2, this.shield + 1);
  }
  private fail(n: ChartNote): JudgeEvent {
    if (this.shield > 0) {
      this.shield--;
      return { grade: 'blocked', lane: n.lane, kind: n.kind, delta: 0 };
    }
    this.miss++;
    this.combo = 0;
    this.health = Math.max(0, this.health - this.drain);
    return { grade: 'miss', lane: n.lane, kind: n.kind, delta: 0 };
  }
}

// Campo de notas: gemas (InstancedMesh), colas de notas largas, líneas de compás, receptores y haces de luz.
import * as THREE from 'three';
import type { ChartNote } from './songs';
import { LANE_COLORS, LANE_X, TRACK_LEN } from './scene';
import { glowTexture } from './three-compat';

const MAX = 160;
const GOLD = 0xffe14a;
const SHIELD = 0x9ff6ff;
const DEAD = new THREE.Color(0x3a3350);

export class NoteField {
  private group = new THREE.Group();
  private gems: THREE.InstancedMesh;
  private cores: THREE.InstancedMesh;
  private glows: THREE.InstancedMesh;
  private tails: THREE.InstancedMesh;
  private beats: THREE.InstancedMesh;
  private receptors: THREE.Mesh[] = [];
  private pads: THREE.Mesh[] = [];
  private beams: THREE.Mesh[] = [];
  private press = [0, 0, 0, 0];
  private flash = [0, 0, 0, 0];
  private disposables: Array<{ dispose(): void }> = [];
  private d = new THREE.Object3D();
  private c = new THREE.Color();
  constructor(scene: THREE.Scene) {
    scene.add(this.group);
    const keep = <T extends { dispose(): void }>(o: T) => { this.disposables.push(o); return o; };
    const glow = keep(glowTexture());
    const add = (geo: THREE.BufferGeometry, mat: THREE.Material, n: number) => {
      const m = new THREE.InstancedMesh(keep(geo), keep(mat), n);
      m.frustumCulled = false;
      for (let i = 0; i < n; i++) m.setColorAt(i, this.c.setHex(0xffffff));
      this.group.add(m);
      return m;
    };
    const additive = (opacity = 1, map?: THREE.Texture) => new THREE.MeshBasicMaterial({ map, transparent: true, opacity, blending: THREE.AdditiveBlending, depthWrite: false });
    this.glows = add(new THREE.PlaneGeometry(3.2, 3.2).rotateX(-Math.PI / 2), additive(0.9, glow), MAX);
    this.tails = add(new THREE.BoxGeometry(1, 1, 1), additive(0.75), 48);
    this.gems = add(new THREE.CylinderGeometry(0.62, 0.74, 0.36, 6), new THREE.MeshBasicMaterial(), MAX);
    this.cores = add(new THREE.CylinderGeometry(0.32, 0.32, 0.4, 6), new THREE.MeshBasicMaterial(), MAX);
    this.beats = add(new THREE.BoxGeometry(6.9, 0.02, 1), additive(0.5), 40);
    const ringG = keep(new THREE.RingGeometry(0.62, 0.8, 6).rotateX(-Math.PI / 2));
    const padG = keep(new THREE.CircleGeometry(0.62, 6).rotateX(-Math.PI / 2));
    const beamG = keep(new THREE.PlaneGeometry(1.5, 9));
    beamG.translate(0, 4.5, 0);
    const beamTex = keep(this.beamTexture());
    for (let l = 0; l < 4; l++) {
      const col = LANE_COLORS[l];
      const ring = new THREE.Mesh(ringG, keep(new THREE.MeshBasicMaterial({ color: col, transparent: true, blending: THREE.AdditiveBlending, depthWrite: false })));
      ring.position.set(LANE_X[l], 0.04, 0); ring.rotation.y = Math.PI / 6;
      const pad = new THREE.Mesh(padG, keep(new THREE.MeshBasicMaterial({ color: col, transparent: true, opacity: 0.15, blending: THREE.AdditiveBlending, depthWrite: false })));
      pad.position.set(LANE_X[l], 0.03, 0); pad.rotation.y = Math.PI / 6;
      const beam = new THREE.Mesh(beamG, keep(new THREE.MeshBasicMaterial({ map: beamTex, color: col, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })));
      beam.position.set(LANE_X[l], 0, -0.2);
      this.group.add(ring, pad, beam);
      this.receptors.push(ring); this.pads.push(pad); this.beams.push(beam);
    }
  }
  private beamTexture() {
    const cv = document.createElement('canvas'); cv.width = 64; cv.height = 128;
    const g = cv.getContext('2d')!;
    const v = g.createLinearGradient(0, 128, 0, 0);
    v.addColorStop(0, 'rgba(255,255,255,1)'); v.addColorStop(0.4, 'rgba(255,255,255,0.35)'); v.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = v; g.fillRect(0, 0, 64, 128);
    g.globalCompositeOperation = 'destination-in';
    const h = g.createLinearGradient(0, 0, 64, 0);
    h.addColorStop(0, 'rgba(0,0,0,0)'); h.addColorStop(0.5, 'rgba(0,0,0,1)'); h.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = h; g.fillRect(0, 0, 64, 128);
    return new THREE.CanvasTexture(cv);
  }
  pressLane(l: number) { this.press[l] = 1; }
  flashLane(l: number, k = 1) { this.flash[l] = Math.max(this.flash[l], k); }
  update(t: number, dt: number, notes: ChartNote[], speed: number, beatDur: number, down: boolean[], fever: boolean, kick: number) {
    const d = this.d, c = this.c;
    let g = 0, tl = 0;
    const spin = t * 2.2;
    for (const n of notes) {
      if (g >= MAX) break;
      if (n.state === 2) continue;
      const holding = n.state === 1;
      const zh = holding ? 0 : -(n.time - t) * speed;
      if (zh < -TRACK_LEN - 2 || zh > 6) continue;
      const x = LANE_X[n.lane];
      const dead = n.state === 3;
      const base = n.kind === 'gold' ? GOLD : n.kind === 'shield' ? SHIELD : LANE_COLORS[n.lane];
      if (n.kind === 'hold' && tl < 48) {
        const ze = Math.min(zh, -(n.end - t) * speed);
        const len = zh - ze;
        if (len > 0.05) {
          d.position.set(x, 0.06, (zh + ze) / 2); d.rotation.set(0, 0, 0);
          d.scale.set(holding ? 0.56 + Math.sin(t * 40) * 0.06 : 0.44, 0.06, len); d.updateMatrix();
          this.tails.setMatrixAt(tl, d.matrix);
          if (dead) c.copy(DEAD); else c.setHex(base).multiplyScalar(holding ? 1.2 : 0.7);
          this.tails.setColorAt(tl++, c);
        }
      }
      const pop = Math.max(0, 1 - Math.abs(zh) / 3) * 0.12;
      d.position.set(x, 0.2, zh);
      d.rotation.set(0, n.kind === 'shield' ? spin : n.kind === 'gold' ? -spin : Math.PI / 6, 0);
      d.scale.set(1 + pop, 1, 1 + pop); d.updateMatrix();
      this.gems.setMatrixAt(g, d.matrix);
      if (dead) c.copy(DEAD); else c.setHex(base);
      this.gems.setColorAt(g, c);
      d.position.y = 0.24; d.scale.set(1, 1, 1); d.updateMatrix();
      this.cores.setMatrixAt(g, d.matrix);
      if (dead) c.copy(DEAD).multiplyScalar(1.4); else c.setHex(n.kind === 'shield' ? 0x2266ff : 0xffffff);
      this.cores.setColorAt(g, c);
      d.position.set(x, 0.02, zh); d.rotation.set(0, 0, 0);
      d.scale.setScalar(n.kind === 'tap' || n.kind === 'hold' ? 1 : 1.5); d.updateMatrix();
      this.glows.setMatrixAt(g, d.matrix);
      if (dead) c.setRGB(0, 0, 0); else c.setHex(base);
      this.glows.setColorAt(g++, c);
    }
    for (const m of [this.gems, this.cores, this.glows]) {
      m.count = g; m.instanceMatrix.needsUpdate = true;
      if (m.instanceColor) m.instanceColor.needsUpdate = true;
    }
    this.tails.count = tl; this.tails.instanceMatrix.needsUpdate = true;
    if (this.tails.instanceColor) this.tails.instanceColor.needsUpdate = true;
    // Líneas de pulso (negras) y de compás que bajan sincronizadas
    let b = 0;
    const approach = TRACK_LEN / speed;
    for (let k = Math.ceil(t / beatDur); k * beatDur < t + approach && b < 40; k++) {
      const z = -(k * beatDur - t) * speed;
      const bar = k % 4 === 0;
      d.position.set(0, 0.012, z); d.rotation.set(0, 0, 0); d.scale.set(1, 1, bar ? 0.14 : 0.05); d.updateMatrix();
      this.beats.setMatrixAt(b, d.matrix);
      c.setHex(fever ? 0xffd040 : bar ? 0xb070ff : 0x5a3c9a).multiplyScalar(bar ? 0.9 : 0.5);
      this.beats.setColorAt(b++, c);
    }
    this.beats.count = b; this.beats.instanceMatrix.needsUpdate = true;
    if (this.beats.instanceColor) this.beats.instanceColor.needsUpdate = true;
    for (let l = 0; l < 4; l++) {
      if (down[l]) this.press[l] = Math.max(this.press[l], 0.6);
      this.press[l] = Math.max(0, this.press[l] - dt * 5);
      this.flash[l] = Math.max(0, this.flash[l] - dt * 3.2);
      const s = 1 + this.press[l] * 0.22 + kick * 0.06;
      this.receptors[l].scale.set(s, 1, s);
      (this.pads[l].material as THREE.MeshBasicMaterial).opacity = 0.12 + this.press[l] * 0.6 + this.flash[l] * 0.4;
      const bm = this.beams[l].material as THREE.MeshBasicMaterial;
      bm.opacity = Math.min(1, this.flash[l] * 0.9 + (down[l] ? 0.18 : 0));
      this.beams[l].scale.set(0.7 + this.flash[l] * 0.5, 0.4 + this.flash[l] * 0.9, 1);
    }
  }
  dispose() {
    this.disposables.forEach(x => x.dispose());
    this.group.parent?.remove(this.group);
  }
}

// Récords por canción y dificultad (localStorage, a prueba de fallos).
export interface SaveData {
  best: Record<string, number>;
  rank: Record<string, string>;
  song: string;
  diff: string;
}

const KEY = 'ritmo-neon-save-v1';

export const bestKey = (song: string, diff: string) => `${song}|${diff}`;

export function loadSave(): SaveData {
  const def: SaveData = { best: {}, rank: {}, song: 'nocturno', diff: 'normal' };
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) return { ...def, ...JSON.parse(raw) };
  } catch { /* sin almacenamiento */ }
  return def;
}

export function storeSave(s: SaveData) {
  try { localStorage.setItem(KEY, JSON.stringify(s)); } catch { /* sin almacenamiento */ }
}

const ORDER = ['F', 'D', 'C', 'B', 'A', 'S'];
export const betterRank = (a: string | undefined, b: string) => (!a || ORDER.indexOf(b) > ORDER.indexOf(a) ? b : a);

// Escenario: cielo, portal-altavoz con láseres, rejilla infinita, autopista de 4 carriles y ecualizadores.
import * as THREE from 'three';
import { glowTexture } from './three-compat';

export const LANE_X = [-2.4, -0.8, 0.8, 2.4];
export const LANE_COLORS = [0xff2fd0, 0x22e6ff, 0xb6ff3b, 0xffa62e];
export const TRACK_LEN = 72;
const FOG = 0x1a0638;

const FLOOR_VS = `varying vec3 vW;
void main(){ vec4 w = modelMatrix * vec4(position,1.0); vW = w.xyz; gl_Position = projectionMatrix * viewMatrix * w; }`;
const FLOOR_FS = `uniform float uScroll; uniform float uPulse; uniform vec3 uA; uniform vec3 uB; varying vec3 vW;
void main(){
  float d = max(0.0, -vW.z);
  vec2 p = vec2(vW.x, vW.z - uScroll) / 3.0;
  float w = 0.035 + d * 0.0011;
  float lx = abs(fract(p.x) - 0.5), lz = abs(fract(p.y) - 0.5);
  float line = max(smoothstep(0.5 - w, 0.5, lx), smoothstep(0.5 - w * 1.3, 0.5, lz));
  vec3 col = mix(uA, uB, smoothstep(-30.0, 30.0, vW.x));
  float side = smoothstep(3.6, 7.0, abs(vW.x));
  vec3 c = col * line * exp(-d * 0.011) * (0.5 + uPulse) * (0.25 + side * 0.75);
  c += mix(vec3(0.015, 0.0, 0.05), vec3(0.32, 0.05, 0.42), smoothstep(90.0, 270.0, d));
  gl_FragColor = vec4(c, 1.0);
}`;
const SKY_VS = `varying vec2 vUv; void main(){ vUv = uv; gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0); }`;
const SKY_FS = `uniform float uTime; uniform float uPulse; uniform vec3 uHorizon; varying vec2 vUv;
float h(vec2 p){ return fract(sin(dot(p, vec2(41.3, 289.1))) * 43758.5); }
void main(){
  float y = vUv.y;
  vec3 top = vec3(0.02, 0.0, 0.06);
  vec3 c = mix(uHorizon * (1.0 + uPulse * 0.35), top, smoothstep(0.0, 0.75, y));
  vec2 g = floor(vUv * vec2(260.0, 70.0));
  float s = step(0.992, h(g)) * smoothstep(0.15, 0.7, y);
  c += s * (0.5 + 0.5 * sin(uTime * 3.0 + h(g + 7.0) * 30.0)) * vec3(0.8, 0.85, 1.0);
  float band = sin(vUv.x * 9.0 + uTime * 0.25 + sin(vUv.x * 3.0 + uTime * 0.4) * 2.0) * 0.5 + 0.5;
  c += vec3(0.25, 0.05, 0.4) * band * smoothstep(0.2, 0.45, y) * smoothstep(0.85, 0.45, y) * 0.35;
  gl_FragColor = vec4(c, 1.0);
}`;

export class World {
  private disposables: Array<{ dispose(): void }> = [];
  private floorU = { uScroll: { value: 0 }, uPulse: { value: 0 }, uA: { value: new THREE.Color(0xff2fd0) }, uB: { value: new THREE.Color(0x22e6ff) } };
  private skyU = { uTime: { value: 0 }, uPulse: { value: 0 }, uHorizon: { value: new THREE.Color(0x4a0f6e) } };
  private rings: THREE.Mesh[] = [];
  private lasers: THREE.Mesh[] = [];
  private arches: THREE.Mesh[] = [];
  private core: THREE.Sprite;
  private towers: THREE.InstancedMesh;
  private towerH: number[] = [];
  private rails: THREE.MeshBasicMaterial[] = [];
  private highway: THREE.MeshBasicMaterial;
  private dummy = new THREE.Object3D();
  private feverMix = 0;
  constructor(private scene: THREE.Scene) {
    scene.background = new THREE.Color(0x05010f);
    scene.fog = new THREE.Fog(FOG, 45, 240);
    const add = <T extends THREE.Object3D>(o: T) => { scene.add(o); return o; };
    const keep = <T extends { dispose(): void }>(o: T) => { this.disposables.push(o); return o; };
    // Cielo
    const skyMat = keep(new THREE.ShaderMaterial({ uniforms: this.skyU, vertexShader: SKY_VS, fragmentShader: SKY_FS, depthWrite: false }));
    const sky = add(new THREE.Mesh(keep(new THREE.PlaneGeometry(900, 220)), skyMat));
    sky.position.set(0, 80, -300);
    // Rejilla del suelo
    const floorMat = keep(new THREE.ShaderMaterial({ uniforms: this.floorU, vertexShader: FLOOR_VS, fragmentShader: FLOOR_FS }));
    const floor = add(new THREE.Mesh(keep(new THREE.PlaneGeometry(600, 300)), floorMat));
    floor.rotation.x = -Math.PI / 2; floor.position.set(0, -0.05, -130);
    // Portal-altavoz: anillos concéntricos, núcleo brillante y láseres
    const glow = keep(glowTexture());
    for (let i = 0; i < 6; i++) {
      const m = keep(new THREE.MeshBasicMaterial({ color: LANE_COLORS[i % 4], transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false, fog: false }));
      const ring = add(new THREE.Mesh(keep(new THREE.TorusGeometry(9 + i * 6, 0.35 + i * 0.05, 8, 96)), m));
      ring.position.set(0, 30, -215);
      this.rings.push(ring);
    }
    this.core = add(new THREE.Sprite(keep(new THREE.SpriteMaterial({ map: glow, color: 0xff4fe0, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true, fog: false }))));
    this.core.position.set(0, 30, -220); this.core.scale.set(110, 110, 1);
    const laserG = keep(new THREE.BoxGeometry(0.5, 420, 0.5)); laserG.translate(0, 210, 0);
    for (let i = 0; i < 6; i++) {
      const m = keep(new THREE.MeshBasicMaterial({ color: LANE_COLORS[(i + 1) % 4], transparent: true, opacity: 0.32, blending: THREE.AdditiveBlending, depthWrite: false, fog: false }));
      const l = add(new THREE.Mesh(laserG, m));
      l.position.set(0, 30, -225);
      this.lasers.push(l);
    }
    // Autopista
    this.highway = keep(new THREE.MeshBasicMaterial({ color: 0x0a0420, transparent: true, opacity: 0.9 }));
    const road = add(new THREE.Mesh(keep(new THREE.PlaneGeometry(7, 110)), this.highway));
    road.rotation.x = -Math.PI / 2; road.position.set(0, 0.005, -47);
    const sepG = keep(new THREE.BoxGeometry(0.05, 0.02, 110));
    const sepM = keep(new THREE.MeshBasicMaterial({ color: 0x4a2c8a }));
    for (const x of [-1.6, 0, 1.6]) add(new THREE.Mesh(sepG, sepM)).position.set(x, 0.02, -47);
    const railG = keep(new THREE.BoxGeometry(0.14, 0.12, 110));
    const railGlowG = keep(new THREE.PlaneGeometry(1.6, 110));
    [-3.5, 3.5].forEach((x, i) => {
      const m = keep(new THREE.MeshBasicMaterial({ color: i ? 0x22e6ff : 0xff2fd0 }));
      this.rails.push(m);
      add(new THREE.Mesh(railG, m)).position.set(x, 0.06, -47);
      const gm = keep(new THREE.MeshBasicMaterial({ map: glow, color: i ? 0x22e6ff : 0xff2fd0, transparent: true, opacity: 0.55, blending: THREE.AdditiveBlending, depthWrite: false }));
      const gl = add(new THREE.Mesh(railGlowG, gm));
      gl.rotation.x = -Math.PI / 2; gl.position.set(x, 0.03, -47); gl.scale.set(1, 1, 1);
    });
    // Arcos de neón que vienen hacia la cámara
    const archG = keep(new THREE.TorusGeometry(5.4, 0.09, 6, 48, Math.PI));
    for (let i = 0; i < 6; i++) {
      const m = keep(new THREE.MeshBasicMaterial({ color: LANE_COLORS[i % 4], transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending, depthWrite: false }));
      this.arches.push(add(new THREE.Mesh(archG, m)));
    }
    // Ecualizadores laterales (altura según la música)
    const tg = keep(new THREE.BoxGeometry(1.1, 1, 1.1));
    const cols: number[] = [];
    const pos = tg.getAttribute('position');
    for (let i = 0; i < pos.count; i++) { const k = pos.getY(i) > 0 ? 1.15 : 0.3; cols.push(k, k, k); }
    tg.setAttribute('color', new THREE.Float32BufferAttribute(cols, 3));
    this.towers = add(new THREE.InstancedMesh(tg, keep(new THREE.MeshBasicMaterial({ vertexColors: true })), 40));
    const c = new THREE.Color();
    for (let i = 0; i < 40; i++) {
      c.setHex(LANE_COLORS[(i >> 1) % 4]);
      this.towers.setColorAt(i, c);
      this.towerH.push(1);
    }
    this.layoutTowers();
  }
  private layoutTowers() {
    for (let i = 0; i < 40; i++) {
      const side = i % 2 ? 1 : -1, row = i >> 1;
      const h = this.towerH[i];
      this.dummy.position.set(side * (9.5 + (row % 3) * 1.8), h / 2, -9 - row * 7);
      this.dummy.scale.set(1, h, 1);
      this.dummy.updateMatrix();
      this.towers.setMatrixAt(i, this.dummy.matrix);
    }
    this.towers.instanceMatrix.needsUpdate = true;
  }

  /** bands: 8 energías 0..1 derivadas de los eventos del secuenciador. */
  update(t: number, dt: number, scroll: number, kick: number, bands: number[], fever: boolean) {
    this.feverMix += ((fever ? 1 : 0) - this.feverMix) * Math.min(1, dt * 4);
    const f = this.feverMix;
    this.floorU.uScroll.value = scroll;
    this.floorU.uPulse.value = kick;
    this.floorU.uA.value.setRGB(1, 0.18 + f * 0.6, 0.82 - f * 0.6);
    this.floorU.uB.value.setRGB(0.13 + f * 0.8, 0.9, 1 - f * 0.7);
    this.skyU.uTime.value = t;
    this.skyU.uPulse.value = kick;
    this.skyU.uHorizon.value.setRGB(0.29 + f * 0.25, 0.06 + f * 0.12, 0.43 - f * 0.2);
    const s = 1 + kick * 0.08;
    this.rings.forEach((r, i) => {
      r.rotation.z = t * (0.12 + i * 0.05) * (i % 2 ? -1 : 1);
      r.rotation.x = Math.sin(t * 0.5 + i) * 0.08;
      r.scale.setScalar(s + Math.sin(t * 2 + i) * 0.015 + bands[i] * 0.07);
      (r.material as THREE.MeshBasicMaterial).opacity = 0.45 + bands[i] * 0.55;
    });
    this.core.scale.setScalar(95 + kick * 45 + f * 30);
    (this.core.material as THREE.SpriteMaterial).color.setRGB(1, 0.3 + f * 0.5, 0.88 - f * 0.6);
    this.lasers.forEach((l, i) => {
      const side = i < 3 ? -1 : 1;
      l.rotation.z = side * (0.35 + (i % 3) * 0.32) + Math.sin(t * (0.7 + i * 0.13) + i) * 0.25;
      (l.material as THREE.MeshBasicMaterial).opacity = 0.12 + bands[(i + 2) % 8] * 0.45 + f * 0.15;
    });
    const span = 6 * 16;
    this.arches.forEach((a, i) => {
      const z = ((i * 16 + scroll * 0.5) % span) - span + 8;
      a.position.set(0, 0, z);
      (a.material as THREE.MeshBasicMaterial).opacity = Math.max(0, Math.min(1, (z + span) / 30, -z / 14)) * (0.5 + kick * 0.5);
    });
    this.rails.forEach((m, i) => m.color.setHex(i ? (f > 0.5 ? 0xffe14a : 0x22e6ff) : 0xff2fd0).multiplyScalar(0.75 + kick * 0.5));
    this.highway.color.setRGB(0.04 + kick * 0.04, 0.016, 0.13 + kick * 0.06);
    for (let i = 0; i < 40; i++) {
      const target = 1 + bands[(i >> 1) % 8] * (10 + ((i * 7) % 5) * 2.2);
      this.towerH[i] += (target - this.towerH[i]) * Math.min(1, dt * (target > this.towerH[i] ? 22 : 6));
    }
    this.layoutTowers();
  }
  dispose() {
    this.disposables.forEach(d => d.dispose());
    this.scene.clear();
  }
}

// Secuenciador único: programa la música con audioContext.currentTime y entrega las notas
// jugables desde la misma partitura y el mismo reloj. Si el audio no arranca, usa un reloj de respaldo.
import type { BuiltSong, ChartNote, Inst } from './songs';
import { sound } from './audio';

export interface Pulse { time: number; inst: Inst; midi: number }

export const LEAD_IN = 1.4;
const LOOKAHEAD = 0.14;

export class Sequencer {
  song: BuiltSong | null = null;
  silent = true;
  useAudio = false;
  paused = false;
  private broken = false;
  private t0 = 0;
  private fb = 0;
  private lastCtx = -1;
  private stall = 0;
  private nextStep = 0;
  private nextNote = 0;
  private pulses: Pulse[] = [];
  start(song: BuiltSong, silent: boolean, from = -LEAD_IN) {
    this.song = song; this.silent = silent; this.paused = false;
    this.useAudio = false; this.fb = from; this.stall = 0;
    this.nextStep = Math.max(0, Math.ceil(from / song.stepDur));
    this.nextNote = 0; this.pulses = [];
    while (this.nextNote < song.notes.length && song.notes[this.nextNote].time < from) this.nextNote++;
    this.tryAudio();
  }
  stop() { this.song = null; this.pulses = []; }

  /** Pasa al reloj del AudioContext en cuanto esté disponible (sin saltos de tiempo). */
  private tryAudio() {
    const c = sound.ctx;
    if (this.silent || this.broken || !c || c.state !== 'running') return;
    this.t0 = c.currentTime - this.fb;
    this.useAudio = true; this.lastCtx = c.currentTime; this.stall = 0;
  }

  /** Tiempo de la canción en segundos (negativo durante la cuenta atrás). */
  time(): number {
    const c = sound.ctx;
    return this.useAudio && c ? c.currentTime - this.t0 : this.fb;
  }
  update(wallDt: number) {
    const song = this.song;
    if (!song || this.paused) return;
    const c = sound.ctx;
    if (this.useAudio && c) {
      // Detecta un reloj de audio congelado (sin salida de audio) y cae al reloj de respaldo
      if (c.state !== 'running' || c.currentTime === this.lastCtx) {
        this.stall += wallDt;
        if (this.stall > 0.45) { this.fb = this.time(); this.useAudio = false; this.broken = true; }
      } else { this.lastCtx = c.currentTime; this.stall = 0; }
    } else {
      this.fb += Math.min(wallDt, 0.5);
      this.tryAudio();
    }
    const now = this.time();
    const ahead = now + LOOKAHEAD;
    while (this.nextStep < song.steps.length && this.nextStep * song.stepDur < ahead) {
      const st = this.nextStep * song.stepDur;
      for (const h of song.steps[this.nextStep]) {
        if (this.useAudio && c && st >= now - 0.03) sound.play(h, this.t0 + st, song.stepDur);
        this.pulses.push({ time: st, inst: h.inst, midi: h.midi });
      }
      this.nextStep++;
    }
  }

  /** Notas que deben empezar a caer (aparecen `approach` segundos antes de su golpe). */
  spawn(approach: number): ChartNote[] {
    const out: ChartNote[] = [];
    const song = this.song; if (!song) return out;
    const lim = this.time() + approach;
    while (this.nextNote < song.notes.length && song.notes[this.nextNote].time < lim) out.push(song.notes[this.nextNote++]);
    return out;
  }

  /** Eventos musicales que ya sonaron (para que el escenario baile al ritmo). */
  takePulses(): Pulse[] {
    const now = this.time();
    const out: Pulse[] = [];
    let i = 0;
    while (i < this.pulses.length && this.pulses[i].time <= now) out.push(this.pulses[i++]);
    if (i) this.pulses.splice(0, i);
    return out;
  }
  pause() {
    if (this.paused) return;
    this.paused = true;
    if (this.useAudio) sound.suspend();
  }
  resume() {
    if (!this.paused) return;
    this.paused = false; this.stall = 0;
    if (this.useAudio) { sound.resume(); this.lastCtx = -1; }
  }
}

// Canciones procedurales: la MISMA partitura genera la música (Hit) y las notas jugables (ChartNote).
export type Inst = 'kick' | 'snare' | 'clap' | 'hat' | 'ohat' | 'bass' | 'lead' | 'pad' | 'arp';
export type Style = 'synth' | 'house' | 'dnb' | 'funk';
export type NoteKind = 'tap' | 'hold' | 'gold' | 'shield';

export interface Hit { inst: Inst; midi: number; len: number; vel: number }
export interface ChartNote {
  id: number; lane: number; time: number; end: number; kind: NoteKind;
  /** 0 pendiente · 1 manteniendo · 2 acertada · 3 fallada */
  state: number;
}
export interface SongDef {
  id: string; name: string; style: Style; bpm: number; root: number; minor: boolean;
  prog: number[]; seed: number; color: string; desc: string; lead: OscillatorType;
}
export interface DiffDef { id: string; name: string; speed: number; window: number; density: number; drain: number; color: string }
export interface Section { name: string; start: number; energy: number }
export interface BuiltSong {
  def: SongDef; stepDur: number; steps: Hit[][]; notes: ChartNote[]; sections: Section[]; duration: number;
}

export const SONGS: SongDef[] = [
  { id: 'nocturno', name: 'Neón Nocturno', style: 'synth', bpm: 108, root: 57, minor: true, prog: [0, 5, 2, 6], seed: 11, color: '#ff2fd0', desc: 'Synthwave de medianoche', lead: 'sawtooth' },
  { id: 'pulso', name: 'Pulso Digital', style: 'house', bpm: 122, root: 53, minor: true, prog: [0, 3, 6, 4], seed: 29, color: '#22e6ff', desc: 'House de club, bombo a negras', lead: 'square' },
  { id: 'cromo', name: 'Corazón Cromado', style: 'funk', bpm: 100, root: 55, minor: false, prog: [0, 3, 4, 3], seed: 47, color: '#ffb02e', desc: 'Funk eléctrico con groove', lead: 'triangle' },
  { id: 'hiper', name: 'Hiperespacio', style: 'dnb', bpm: 150, root: 52, minor: true, prog: [0, 0, 5, 6], seed: 83, color: '#b6ff3b', desc: 'Drum & bass a toda velocidad', lead: 'sawtooth' },
];

export const DIFFS: DiffDef[] = [
  { id: 'facil', name: 'Fácil', speed: 17, window: 1.3, density: 0, drain: 2, color: '#b6ff3b' },
  { id: 'normal', name: 'Normal', speed: 21, window: 1.0, density: 1, drain: 2.5, color: '#22e6ff' },
  { id: 'dificil', name: 'Difícil', speed: 26, window: 0.9, density: 2, drain: 3.5, color: '#ffb02e' },
  { id: 'experto', name: 'Experto', speed: 31, window: 0.8, density: 3, drain: 4.5, color: '#ff2fd0' },
];

// [nombre, compases, energía, ¿bombo?]
const FORM: Array<[string, number, number, boolean]> = [
  ['Intro', 2, 0, true], ['Verso', 8, 1, true], ['Estribillo', 8, 2, true], ['Verso', 8, 1, true],
  ['Puente', 4, 1, false], ['Estribillo final', 8, 3, true], ['Final', 2, 0, true],
];

const DRUMS: Record<Style, Partial<Record<Inst, string>>> = {
  synth: { kick: 'x...x...x...x...', snare: '....x.......x...', hat: '..x...x...x...x.' },
  house: { kick: 'x...x...x...x...', clap: '....x.......x...', ohat: '..x...x...x...x.', hat: '.x.x.x.x.x.x.x.x' },
  funk: { kick: 'x..x..x...x..x..', snare: '....x.......x..x', hat: 'xxxxxxxxxxxxxxxx' },
  dnb: { kick: 'x.........x.....', snare: '....x.......x...', hat: 'x.x.x.x.x.x.x.xx' },
};
const BASS: Record<Style, string> = {
  synth: 'x.x.x.x.x.x.x.x.', house: '..x...x...x...x.', funk: 'x..o..x.x..o.x.o', dnb: 'x.......x..x....',
};
const RHYTHMS: number[][][] = [
  [[0, 4, 8, 12], [0, 6, 8, 12], [0, 8, 12], [0, 4, 10]],
  [[0, 3, 6, 8, 12, 14], [0, 2, 4, 8, 10, 12], [0, 4, 6, 10, 12], [0, 3, 6, 10, 12, 14]],
  [[0, 2, 4, 6, 8, 10, 12, 14], [0, 2, 3, 6, 8, 10, 11, 14], [0, 3, 4, 6, 8, 11, 12, 14], [0, 2, 4, 7, 8, 10, 12, 15]],
];

function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function degToMidi(root: number, minor: boolean, deg: number) {
  const sc = minor ? [0, 2, 3, 5, 7, 8, 10] : [0, 2, 4, 5, 7, 9, 11];
  const o = Math.floor(deg / 7);
  return root + o * 12 + sc[((deg % 7) + 7) % 7];
}

interface Motif { on: number[]; off: number[]; rest: boolean }
/** rest = frase de respuesta: termina a mitad de compás para respirar. */
function makeMotif(r: () => number, energy: number, rest: boolean): Motif {
  const pool = RHYTHMS[Math.min(2, energy)];
  let on = pool[Math.floor(r() * pool.length)].slice();
  if (energy >= 3 && r() < 0.6) { const extra = [5, 9, 13][Math.floor(r() * 3)]; if (!on.includes(extra)) on.push(extra); on.sort((a, b) => a - b); }
  const off: number[] = [];
  let d = [0, 2, 4][Math.floor(r() * 3)];
  for (const s of on) {
    if (s % 4 === 0) d = [0, 2, 4, 7][Math.floor(r() * 4)];
    else d += r() < 0.5 ? 1 : -1 + (r() < 0.3 ? -1 : 0);
    off.push(Math.max(-2, Math.min(9, d)));
  }
  if (rest) { on = on.filter(s => s <= 8); off.length = on.length; }
  return { on, off, rest };
}

/** Construye la canción completa: pistas de audio por paso y la partitura jugable para la dificultad. */
export function buildSong(def: SongDef, diff: DiffDef): BuiltSong {
  const r = rng(def.seed);
  const stepDur = 60 / def.bpm / 4;
  const totalBars = FORM.reduce((a, f) => a + f[1], 0);
  const steps: Hit[][] = Array.from({ length: totalBars * 16 }, () => []);
  const notes: ChartNote[] = [];
  const sections: Section[] = [];
  const dens = diff.density;
  let bar = 0, lane = 1, prevMidi = -1, id = 0, lastNoteStep = -99;

  const addNote = (step: number, ln: number, kind: NoteKind, len: number) => {
    const time = step * stepDur;
    notes.push({ id: id++, lane: ln, time, end: kind === 'hold' ? time + (len - 0.6) * stepDur : time, kind, state: 0 });
  };

  FORM.forEach(([name, bars, energy, kickOn], fi) => {
    // Corte antes de subir de energía: la melodía calla un compás y entra un redoble
    const brk = bars >= 4 && (FORM[fi + 1]?.[2] ?? 0) > energy;
    sections.push({ name, start: bar * 16 * stepDur, energy });
    const mA = makeMotif(r, energy, false), mB = makeMotif(r, energy, true);
    for (let b = 0; b < bars; b++, bar++) {
      const base = bar * 16;
      const chord = def.prog[bar % 4];
      const dr = DRUMS[def.style];
      // Batería
      for (let s = 0; s < 16; s++) {
        const at = steps[base + s];
        const kick = dr.kick?.[s] === 'x';
        if (kick && (kickOn || b === bars - 1 && s >= 12)) at.push({ inst: 'kick', midi: 0, len: 1, vel: 1 });
        if (bar === 0) continue;
        if (brk && b === bars - 1 && s >= 8) at.push({ inst: 'snare', midi: 0, len: 1, vel: 0.35 + (s - 8) * 0.08 });
        else if (energy >= 1 && dr.snare?.[s] === 'x') at.push({ inst: 'snare', midi: 0, len: 1, vel: 0.9 });
        if (energy >= 1 && dr.clap?.[s] === 'x') at.push({ inst: 'clap', midi: 0, len: 1, vel: 0.9 });
        if (energy >= 3 && s % 8 === 4 && !dr.clap) at.push({ inst: 'clap', midi: 0, len: 1, vel: 0.6 });
        if (dr.hat?.[s] === 'x' && (energy >= 1 || s % 4 === 2)) at.push({ inst: 'hat', midi: 0, len: 1, vel: s % 4 === 0 ? 0.9 : 0.55 });
        if (energy >= 2 && dr.ohat?.[s] === 'x') at.push({ inst: 'ohat', midi: 0, len: 1, vel: 0.7 });
      }
      // Bajo, pad y arpegio
      const bassRoot = degToMidi(def.root - 24, def.minor, chord);
      const bp = BASS[def.style];
      if (bar > 0) for (let s = 0; s < 16; s++) {
        if (bp[s] === '.') continue;
        let len = 1; while (s + len < 16 && bp[s + len] === '.' && len < 6) len++;
        steps[base + s].push({ inst: 'bass', midi: bassRoot + (bp[s] === 'o' ? 12 : 0), len, vel: 0.9 });
      }
      if (energy >= 1 || !kickOn) for (const k of [0, 2, 4]) steps[base].push({ inst: 'pad', midi: degToMidi(def.root - 12, def.minor, chord + k), len: 16, vel: 0.5 });
      if (energy >= 2) for (let s = 0; s < 16; s++) {
        steps[base + s].push({ inst: 'arp', midi: degToMidi(def.root + 12, def.minor, chord + [0, 2, 4, 7][s % 4]), len: 1, vel: s % 4 === 0 ? 0.5 : 0.3 });
      }
      if (bar === 0 || brk && b === bars - 1) continue;
      // Melodía (lead) + partitura derivada de ella
      const m = b % 2 === 1 || brk && b === bars - 2 ? mB : mA;
      for (let i = 0; i < m.on.length; i++) {
        const s = m.on[i];
        const last = i + 1 >= m.on.length;
        const len = Math.min(last && m.rest ? 4 : 8, (last ? 16 : m.on[i + 1]) - s);
        const midi = degToMidi(def.root, def.minor, chord + m.off[i]);
        steps[base + s].push({ inst: 'lead', midi, len, vel: 0.8 });
        const step = base + s;
        const keep = dens >= 2 || (dens === 1 ? s % 2 === 0 : s % 4 === 0 && step - lastNoteStep >= 4);
        if (!keep) continue;
        // Carril según el contorno melódico
        if (prevMidi >= 0) {
          const dv = midi - prevMidi;
          const nl = Math.max(0, Math.min(3, lane + (dv > 4 ? 2 : dv > 0 ? 1 : dv < -4 ? -2 : dv < 0 ? -1 : 0)));
          lane = nl === lane && dv !== 0 ? (lane === 3 ? 2 : lane === 0 ? 1 : lane + Math.sign(dv)) : nl;
        }
        prevMidi = midi;
        let kind: NoteKind = len >= (dens >= 2 ? 4 : 6) && s % 4 === 0 ? 'hold' : 'tap';
        if (kind === 'tap' && energy >= 2 && b % 2 === 0 && i === 0) kind = 'gold';
        if (kind === 'tap' && energy === 1 && name === 'Verso' && b === 3 && i === 0) kind = 'shield';
        addNote(step, lane, kind, len);
        lastNoteStep = step;
        if (dens >= 2 && energy >= 2 && s === 0) addNote(step, (lane + 2) % 4, 'tap', 1);
      }
      // Experto: golpes de bombo sin melodía se vuelven notas extra
      if (dens >= 3 && energy >= 2) for (let s = 4; s < 16; s += 4) {
        if (m.on.includes(s) || !steps[base + s].some(h => h.inst === 'kick')) continue;
        addNote(base + s, (lane + 1 + (s >> 2)) % 4, 'tap', 1);
      }
    }
  });
  notes.sort((a, b) => a.time - b.time || a.lane - b.lane);
  // Sin solapes en un mismo carril (notas pegadas o dentro de una nota larga)
  const busy = [-1, -1, -1, -1];
  const clean = notes.filter(n => {
    if (n.time < busy[n.lane] + stepDur * 0.9) return false;
    busy[n.lane] = n.end;
    return true;
  });
  clean.forEach((n, i) => { n.id = i; });
  return { def, stepDur, steps, notes: clean, sections, duration: totalBars * 16 * stepDur };
}

import * as THREE from 'three';

const T = THREE as any;
// Sin gestión de color: los colores escritos son los que se ven, igual en r128 y r170.
if (T.ColorManagement) T.ColorManagement.enabled = false;

/** Multiplica TODAS las intensidades de luz (r155+ usa unidades físicas). */
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1;

/** Salida lineal coherente en ambas versiones (neón saturado idéntico). */
export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.LinearSRGBColorSpace; else a.outputEncoding = T.LinearEncoding;
}

export function srgbTexture(t: THREE.Texture) {
  const a = t as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding;
  return t;
}

/** Textura de degradado radial (brillo suave) dibujada en Canvas 2D. */
export function glowTexture(inner = 'rgba(255,255,255,1)', mid = 'rgba(255,255,255,0.35)'): THREE.CanvasTexture {
  const c = document.createElement('canvas');
  c.width = c.height = 128;
  const g = c.getContext('2d')!;
  const gr = g.createRadialGradient(64, 64, 0, 64, 64, 64);
  gr.addColorStop(0, inner); gr.addColorStop(0.25, mid); gr.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = gr; g.fillRect(0, 0, 128, 128);
  return new THREE.CanvasTexture(c);
}

.rn-root { font-family: 'Segoe UI', 'Helvetica Neue', Arial, sans-serif; -webkit-user-select: none; user-select: none; touch-action: none; }
.rn-title {
  font-weight: 900; font-style: italic; letter-spacing: 0.02em; color: transparent;
  background: linear-gradient(95deg, #ff2fd0 0%, #ff8ae8 30%, #22e6ff 62%, #b6ff3b 100%);
  -webkit-background-clip: text; background-clip: text;
  filter: drop-shadow(0 0 22px rgba(255, 47, 208, 0.55)) drop-shadow(0 3px 0 rgba(10, 0, 30, 0.9));
}
.rn-glass {
  background: linear-gradient(160deg, rgba(28, 8, 64, 0.78), rgba(6, 2, 20, 0.84));
  border: 1px solid rgba(160, 110, 255, 0.28);
  box-shadow: 0 0 26px rgba(120, 60, 255, 0.18), inset 0 0 20px rgba(34, 230, 255, 0.05);
  backdrop-filter: blur(6px);
}
.rn-btn {
  background: linear-gradient(90deg, #ff2fd0, #a35bff 50%, #22e6ff); color: #fff; font-weight: 900; letter-spacing: 0.16em;
  text-shadow: 0 1px 0 rgba(30, 0, 60, 0.6);
  box-shadow: 0 0 24px rgba(255, 47, 208, 0.55), 0 0 60px rgba(34, 230, 255, 0.25);
  transition: transform 0.12s ease, box-shadow 0.2s ease;
}
.rn-btn:hover { transform: translateY(-2px) scale(1.02); box-shadow: 0 0 34px rgba(255, 47, 208, 0.8), 0 0 80px rgba(34, 230, 255, 0.4); }
.rn-btn:active { transform: scale(0.97); }
.rn-neon { text-shadow: 0 0 10px currentColor, 0 0 26px currentColor; }
.rn-mono { font-family: 'Consolas', 'SF Mono', 'Menlo', monospace; font-variant-numeric: tabular-nums; }
.rn-vignette { pointer-events: none; background: radial-gradient(ellipse at 50% 55%, rgba(0, 0, 0, 0) 55%, rgba(4, 0, 14, 0.75) 100%); }
/* Sin mix-blend-mode: en equipos modestos cuesta muchos fps */
.rn-scan { pointer-events: none; background: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.025) 0 1px, transparent 1px 3px); }

@keyframes rn-pop {
  0% { transform: translate(-50%, 0) scale(1.6); opacity: 0; }
  15% { transform: translate(-50%, 0) scale(1); opacity: 1; }
  75% { transform: translate(-50%, -8px) scale(1); opacity: 1; }
  100% { transform: translate(-50%, -22px) scale(0.92); opacity: 0; }
}
.rn-pop { animation: rn-pop 0.55s ease-out forwards; }
@keyframes rn-combo { 0% { transform: scale(1.25); } 100% { transform: scale(1); } }
.rn-combo { animation: rn-combo 0.15s ease-out; }
@keyframes rn-banner {
  0% { transform: translateX(-50%) scaleX(0.2); opacity: 0; letter-spacing: 0.6em; }
  15% { transform: translateX(-50%) scaleX(1); opacity: 1; letter-spacing: 0.3em; }
  80% { opacity: 1; }
  100% { transform: translateX(-50%) scaleX(1.05); opacity: 0; letter-spacing: 0.4em; }
}
.rn-banner { animation: rn-banner 1.4s ease-out forwards; }
@keyframes rn-float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-6px); } }
.rn-float { animation: rn-float 3s ease-in-out infinite; }
@keyframes rn-fever { 0%, 100% { box-shadow: 0 0 12px #ffe14a; } 50% { box-shadow: 0 0 30px #ffe14a, 0 0 60px #ff9a2e; } }
.rn-fever { animation: rn-fever 0.5s ease-in-out infinite; }
@keyframes rn-flash { 0% { opacity: 0.45; } 100% { opacity: 0; } }
.rn-flash { animation: rn-flash 0.35s ease-out forwards; }
